def expandable_diagnostic_card(title, summary_html, detail_render_fn):
    """
    Renders a summary card that expands into detailed diagnostics.
    title: expander label
    summary_html: HTML string for the always-visible summary
    detail_render_fn: callable that renders expanded diagnostic content
    """
    with st.expander(title, expanded=False):
        st.markdown(summary_html, unsafe_allow_html=True)
        st.markdown("---")
        detail_render_fn()


@st.cache_data(ttl=600)
def load_ticker_metrics():
    prices_path = Path(_data_path("data/prices.csv"))
    if not prices_path.exists():
        return {}
    try:
        pdf = pd.read_csv(prices_path, parse_dates=["date"])
        pdf = pdf.sort_values(["ticker", "date"])
        metrics = {}
        for ticker, grp in pdf.groupby("ticker"):
            if len(grp) < 22:
                continue
            grp = grp.tail(252).copy()
            grp["log_ret"] = np.log(grp["close"] / grp["close"].shift(1))
            recent = grp.tail(30)
            vol_30d = recent["log_ret"].std() * np.sqrt(252) if len(recent) > 5 else None
            ret_30d = (grp["close"].iloc[-1] / grp.iloc[-min(30, len(grp))]["close"] - 1) if len(grp) >= 30 else None
            ret_60d = (grp["close"].iloc[-1] / grp.iloc[-min(60, len(grp))]["close"] - 1) if len(grp) >= 60 else None
            metrics[ticker] = {
                "vol_30d": vol_30d,
                "ret_30d": ret_30d,
                "ret_60d": ret_60d,
            }
        return metrics
    except Exception:
        return {}


@st.cache_data(show_spinner=False)
def load_attribution_df():
    import pandas as pd, os
    path = "data/alpha_attribution_summary.csv"
    if not os.path.exists(path):
        st.error(f"Missing attribution data source: {path}")
        return pd.DataFrame()
    return pd.read_csv(path)


