def load_snapshot():
    if not LIVE_SNAPSHOT_PATH.exists():
        # Attempt to generate the live snapshot before failing
        try:
            import subprocess
            gen_script = BASE_DIR / "scripts" / "generate_live_snapshot_csv.py"
            if gen_script.exists():
                result = subprocess.run(
                    ["python", str(gen_script)],
                    cwd=str(BASE_DIR),
                    timeout=120,
                    capture_output=True,
                )
                if result.returncode != 0:
                    print(f"[SNAPSHOT] Generation script exited with code {result.returncode}: {result.stderr.decode(errors='replace')[:500]}")
        except subprocess.TimeoutExpired:
            print("[SNAPSHOT] Generation script timed out")
        except Exception as _gen_err:
            print(f"[SNAPSHOT] Generation failed: {_gen_err}")
        if not LIVE_SNAPSHOT_PATH.exists():
            return None, None, "Live snapshot file not found"

    df = pd.read_csv(LIVE_SNAPSHOT_PATH)
    df.columns = [c.strip().lower() for c in df.columns]

    # Load alpha attribution summary if it exists
    attrib_df = None
    if ALPHA_ATTRIBUTION_PATH.exists():
        try:
            attrib_df = pd.read_csv(ALPHA_ATTRIBUTION_PATH)
            attrib_df.columns = [c.strip().lower() for c in attrib_df.columns]
        except Exception:
            pass

    # Load Governance Policy Registry
    try:
        policy_path = Path("governance/policy_registry.json")
        if policy_path.exists():
            with open(policy_path, "r") as f:
                reg_data = json.load(f)
                curr_ver = reg_data.get("current_version", "1.0.0")
                history = reg_data.get("history", [])
                active_policy = next((h for h in history if h.get("policy_version") == curr_ver), history[0] if history else {})
                st.session_state["governance_policy"] = active_policy
        else:
            st.session_state["governance_policy"] = {"policy_version": "0.0.0", "policies": [], "status": "Unknown"}
    except Exception:
        st.session_state["governance_policy"] = {"policy_version": "0.0.0", "policies": [], "status": "Error"}

    # Set display_name
    if "display_name" not in df.columns:
        if "wave" in df.columns:
            df["display_name"] = df["wave"]
        elif "wave_name" in df.columns:
            df["display_name"] = df["wave_name"]
        elif "wave_id" in df.columns:
            df["display_name"] = df["wave_id"]
        else:
            df["display_name"] = "Unnamed Wave"

    if CANONICAL_WAVES:
        st.session_state["available_waves"] = list(CANONICAL_WAVES)
    else:
        waves_list = []
        if "display_name" in df.columns:
            waves_list = sorted(df["display_name"].dropna().unique().tolist())
        st.session_state["available_waves"] = waves_list

    # Ensure required columns exist
    for col in list(RETURN_COLS.values()) + list(ALPHA_COLS.values()):
        if col not in df.columns:
            df[col] = np.nan

    if "intraday_label" not in df.columns:
        df["intraday_label"] = None

    return df, attrib_df, None


def get_market_status():
    """
    Determine market status and intraday data state.
    Returns tuple: (status_code, status_label, is_live)
    
    Status codes:
    - 'live': Market is open, live intraday data
    - 'closed_today': Market closed, same trading day data
    - 'closed_session': Weekend/holiday, last trading session data
    """
    from datetime import datetime, time
    import pytz
    
    try:
        et = pytz.timezone('US/Eastern')
        now = datetime.now(et)
        current_time = now.time()
        weekday = now.weekday()  # 0=Monday, 6=Sunday
        
        # Market hours: 9:30 AM - 4:00 PM ET, Monday-Friday
        market_open = time(9, 30)
        market_close = time(16, 0)
        
        if weekday >= 5:  # Weekend
            return 'closed_session', 'Last trading session', False
        elif market_open <= current_time <= market_close:
            return 'live', 'Live', True
        elif current_time > market_close:
            return 'closed_today', 'As of market close', False
        else:  # Before market open
            return 'closed_session', 'Last trading session', False
    except Exception:
        # Fallback if timezone detection fails
        return 'closed_session', 'Last session', False


def get_intraday_label(market_status):
    """
    Generate display label for intraday data based on market status.
    """
    status_code, status_label, is_live = market_status
    
    if status_code == 'live':
        return "INTRADAY"
    elif status_code == 'closed_today':
        return "INTRADAY (as of close)"
    else:
        return "INTRADAY (last session)"


def has_valid_intraday_data(snapshot_df):
    """
    Check if there's valid intraday data from the trading session.
    
    Returns tuple: (has_any_data, has_nonzero_data)
    - has_any_data: True if columns exist with non-null values (even if zero)
    - has_nonzero_data: True if any wave has non-zero intraday return or alpha
    
    This distinction allows us to differentiate between:
    - No data available (show "-")
    - True zero movement (show "0.00%" as valid data)
    """
    if snapshot_df is None or snapshot_df.empty:
        return False, False
    
    has_any_data = False
    has_nonzero_data = False
    
    for col in ["return_1d", "alpha_1d"]:
        if col in snapshot_df.columns:
            valid_values = snapshot_df[col].dropna()
            if len(valid_values) > 0:
                has_any_data = True
                if (valid_values.abs() > 1e-10).any():
                    has_nonzero_data = True
    
    return has_any_data, has_nonzero_data


# ===========================
# Live System Initialization
# ===========================

def _parse_benchmark_spec(spec_str):
    """Parse 'QQQ:0.6,SMH:0.25,IGV:0.15' into {'QQQ': 0.6, 'SMH': 0.25, 'IGV': 0.15}."""
    result = {}
    for part in str(spec_str).split(","):
        part = part.strip()
        if ":" in part:
            ticker, weight = part.split(":", 1)
            try:
                result[ticker.strip()] = float(weight.strip())
            except (ValueError, TypeError):
                pass
    return result if result else {"SPY": 1.0}


def _compute_weighted_return(prices_pivot, ticker_weights, days):
    """Compute weighted portfolio return over a lookback of ``days`` trading rows."""
    if prices_pivot is None or (isinstance(prices_pivot, pd.DataFrame) and prices_pivot.empty):
        return np.nan
    if not ticker_weights:
        return np.nan

    weighted_sum = 0.0
    total_weight = 0.0

    for ticker, weight in ticker_weights:
        if ticker not in prices_pivot.columns:
            continue
        series = prices_pivot[ticker].dropna()
        if len(series) < 2:
            continue
        needed_rows = min(days, len(series) - 1)
        end_price = series.iloc[-1]
        start_price = series.iloc[-1 - needed_rows]
        if start_price <= 0:
            continue
        ret = (end_price / start_price) - 1.0
        weighted_sum += weight * ret
        total_weight += weight

    if total_weight <= 0:
        return np.nan
    return weighted_sum / total_weight


def _compute_weighted_price_series(prices_pivot, ticker_weights):
    """Build a composite price series by weighting each ticker's close prices.

    Returns a pd.Series indexed by date, or an empty Series if data is unavailable.
    """
    if prices_pivot is None or (isinstance(prices_pivot, pd.DataFrame) and prices_pivot.empty) or not ticker_weights:
        return pd.Series(dtype=float)
    available = [(t, w) for t, w in ticker_weights if t in prices_pivot.columns]
    if not available:
        return pd.Series(dtype=float)
    total_weight = sum(w for _, w in available)
    if total_weight <= 0:
        return pd.Series(dtype=float)
    composite = None
    for ticker, weight in available:
        series = prices_pivot[ticker].ffill()
        scaled = series * (weight / total_weight)
        composite = scaled if composite is None else composite.add(scaled, fill_value=0.0)
    return composite.dropna() if composite is not None else pd.Series(dtype=float)


def expand_wave_holdings():
    """Load wave holdings from data/wave_weights.csv.

    Returns a dict ``{wave_name: [(ticker, weight), ...]}``.
    """
    weights_path = BASE_DIR / "data" / "wave_weights.csv"
    if not weights_path.exists():
        print("[LIVE] expand_wave_holdings: wave_weights.csv not found")
        return {}
    try:
        df = pd.read_csv(weights_path)
        wave_col = "wave_id" if "wave_id" in df.columns else ("wave_name" if "wave_name" in df.columns else None)
        if wave_col is None:
            print("[LIVE] expand_wave_holdings: no wave column found")
            return {}
        holdings = {}
        for wave_name, grp in df.groupby(wave_col):
            tickers = []
            for _, row in grp.iterrows():
                ticker = str(row.get("ticker", "")).strip()
                try:
                    weight = float(row.get("weight", 0))
                except (ValueError, TypeError):
                    weight = 0.0
                if ticker and weight > 0:
                    tickers.append((ticker, weight))
            if tickers:
                holdings[str(wave_name)] = tickers
        print(f"[LIVE] expand_wave_holdings: loaded {len(holdings)} waves")
        return holdings
    except Exception as e:
        print(f"[LIVE] expand_wave_holdings error: {e}")
        return {}


def fetch_prices_for_holdings(holdings):
    """Load price data from data/prices.csv for all holdings tickers.

    Returns a pivoted DataFrame (date index × ticker columns) of close prices,
    or an empty DataFrame if the price file is unavailable.
    """
    prices_path = BASE_DIR / "data" / "prices.csv"
    if not prices_path.exists():
        print("[LIVE] fetch_prices_for_holdings: prices.csv not found")
        return pd.DataFrame()
    try:
        all_tickers = set()
        for tickers in holdings.values():
            for ticker, _ in tickers:
                all_tickers.add(ticker)
        all_tickers.add("SPY")

        prices_df = pd.read_csv(prices_path, parse_dates=["date"])
        prices_df = prices_df[prices_df["ticker"].isin(all_tickers)]
        prices_df = prices_df.sort_values("date")
        pivot = prices_df.pivot(index="date", columns="ticker", values="close")
        pivot.sort_index(inplace=True)
        print(f"[LIVE] fetch_prices_for_holdings: loaded prices for {len(pivot.columns)} tickers, {len(pivot)} rows")
        return pivot
    except Exception as e:
        print(f"[LIVE] fetch_prices_for_holdings error: {e}")
        return pd.DataFrame()


def generate_full_snapshot(holdings, prices_pivot):
    """Compute weighted wave returns and write to data/live_snapshot.csv.

    Populates return_1d / return_30d / return_60d / return_365d and the
    corresponding alpha columns (wave return minus benchmark return).
    """
    if not holdings or prices_pivot is None or (isinstance(prices_pivot, pd.DataFrame) and prices_pivot.empty):
        print("[LIVE] generate_full_snapshot: insufficient data, skipping")
        return

    benchmarks = {}
    registry_path = BASE_DIR / "data" / "wave_registry.csv"
    if registry_path.exists():
        try:
            reg = pd.read_csv(registry_path)
            for _, row in reg.iterrows():
                wname = str(row.get("wave_name", "")).strip()
                bench_spec = str(row.get("benchmark_spec", "")).strip()
                if wname and bench_spec and bench_spec.lower() not in ("nan", "none", ""):
                    benchmarks[wname] = list(_parse_benchmark_spec(bench_spec).items())
        except Exception as e:
            print(f"[LIVE] benchmark spec read error: {e}")

    asof_date = prices_pivot.index.max().strftime("%Y-%m-%d") if not prices_pivot.empty else datetime.utcnow().strftime("%Y-%m-%d")
    horizons = [("1d", 1), ("30d", 30), ("60d", 60), ("365d", 365)]
    attribution_cols = [
        "alpha_residual_30d", "alpha_residual_60d", "alpha_residual_365d",
        "alpha_momentum_30d", "alpha_momentum_60d", "alpha_momentum_365d",
        "alpha_volatility_30d", "alpha_volatility_60d", "alpha_volatility_365d",
        "alpha_beta_30d", "alpha_beta_60d", "alpha_beta_365d",
        "alpha_allocation_30d", "alpha_allocation_60d", "alpha_allocation_365d",
    ]
    try:
        from attribution_engine import compute_horizon_attribution as _compute_ha
        _attr_engine_available = True
    except Exception as _attr_import_err:
        _attr_engine_available = False
        print(f"[LIVE] attribution_engine unavailable: {_attr_import_err}")

    _attr_engine_weights = {"beta": 1.0, "momentum": 1.0, "volatility": 1.0, "allocation": 1.0}

    rows = []
    for wave_name, tickers in holdings.items():
        row = {"wave_name": wave_name, "asof": asof_date}
        bench_tickers = benchmarks.get(wave_name, [("SPY", 1.0)])
        for label, days in horizons:
            wave_ret = _compute_weighted_return(prices_pivot, tickers, days)
            bench_ret = _compute_weighted_return(prices_pivot, bench_tickers, days)
            row[f"return_{label}"] = wave_ret
            row[f"alpha_{label}"] = (wave_ret - bench_ret) if not (np.isnan(wave_ret) or np.isnan(bench_ret)) else np.nan
        for col in attribution_cols:
            row[col] = np.nan
        # Compute price series for drawdown and benchmark volatility (always, not just when attr engine available)
        wave_series = _compute_weighted_price_series(prices_pivot, tickers)
        bench_series = _compute_weighted_price_series(prices_pivot, bench_tickers)
        # drawdown_30d: maximum drawdown of wave composite over last 30 trading days
        if len(wave_series) >= 2:
            _ws_recent = wave_series.iloc[-31:]
            _ws_peak = _ws_recent.cummax()
            _ws_dd = ((_ws_recent - _ws_peak) / _ws_peak).min()
            row["drawdown_30d"] = float(abs(_ws_dd)) if not np.isnan(_ws_dd) else np.nan
        else:
            row["drawdown_30d"] = np.nan
        # benchmark_volatility_30d: annualised std dev of benchmark daily returns over 30 days
        if len(bench_series) >= 2:
            _bs_rets = bench_series.pct_change().dropna().iloc[-30:]
            row["benchmark_volatility_30d"] = float(_bs_rets.std() * np.sqrt(252)) if len(_bs_rets) >= 5 else np.nan
        else:
            row["benchmark_volatility_30d"] = np.nan
        if _attr_engine_available:
            if len(wave_series) >= 2 and len(bench_series) >= 2:
                for attr_days, label in [(30, "30d"), (60, "60d"), (365, "365d")]:
                    try:
                        attr = _compute_ha(wave_series, bench_series, _attr_engine_weights, attr_days)
                        row[f"alpha_residual_{label}"] = attr.get("residual", np.nan)
                        row[f"alpha_momentum_{label}"] = attr.get("momentum", np.nan)
                        row[f"alpha_volatility_{label}"] = attr.get("volatility", np.nan)
                        row[f"alpha_beta_{label}"] = attr.get("beta", np.nan)
                        row[f"alpha_allocation_{label}"] = attr.get("allocation", np.nan)
                    except Exception:
                        pass
        rows.append(row)

    if not rows:
        print("[LIVE] generate_full_snapshot: no rows generated")
        return

    snap = pd.DataFrame(rows)
    output_path = LIVE_SNAPSHOT_PATH
    output_path.parent.mkdir(parents=True, exist_ok=True)
    snap.to_csv(output_path, index=False)
    print(f"[LIVE] generate_full_snapshot: wrote {len(snap)} waves to {output_path}")


def queue_startup_governance_decisions(snap_df):
    """Generate and persist governance decisions for each wave at startup.

    Uses ``generate_decisions`` from the decision engine to build actionable
    governance items based on the freshly computed snapshot data, then persists
    them to ``data/governance_decisions.json`` via the governance lifecycle helper.
    """
    try:
        from decision_engine import generate_decisions as _gen_decisions
        from helpers.governance_lifecycle import create_governance_decision
        import hashlib

        if snap_df is None or snap_df.empty:
            print("[LIVE] queue_startup_governance_decisions: no snapshot data")
            return

        # Placeholder text returned by generate_decisions when no real items exist
        _NO_ACTION_MARKER = "No urgent actions"
        _NO_WATCH_MARKER = "No major watch items"

        decisions_created = 0
        for _, row in snap_df.iterrows():
            wave_name = str(row.get("wave_name", "")).strip()
            if not wave_name:
                continue

            ctx = {
                "a30": row.get("alpha_30d"),
                "a60": row.get("alpha_60d"),
                "a365": row.get("alpha_365d"),
            }

            result = _gen_decisions(ctx)
            actions = result.get("actions", [])
            watch = result.get("watch", [])

            governance_items = [
                (a, "action") for a in actions if _NO_ACTION_MARKER not in a
            ] + [
                (w, "monitor") for w in watch if _NO_WATCH_MARKER not in w
            ]

            # Limit to 2 items per wave to avoid flooding the governance queue
            _id_prefix = f"startup_{wave_name.lower().replace(' ', '_')}"
            for item_text, item_type in governance_items[:2]:
                _id_key = f"{_id_prefix}_{item_type}_{item_text[:64]}"
                decision_id = f"{_id_prefix}_{hashlib.md5(_id_key.encode()).hexdigest()[:8]}"
                create_governance_decision(
                    decision_id=decision_id,
                    wave=wave_name,
                    instruction_type="system_generated",
                    trigger_source="startup_pipeline",
                    context_snapshot={
                        "action": item_text,
                        "item_type": item_type,
                        "snapshot_asof": str(row.get("asof", "")),
                    },
                    source="initialize_live_system",
                )
                decisions_created += 1

        print(f"[LIVE] queue_startup_governance_decisions: created {decisions_created} decisions")
    except Exception as e:
        print(f"[LIVE] queue_startup_governance_decisions error: {e}")


def initialize_live_system():
    """Run the full live intelligence initialization sequence at startup.

    Expands wave holdings from the canonical weights file, loads cached
    price data, then computes and writes a fresh live_snapshot.csv.
    Also triggers holdings evaluation and strategy optimization scoring
    so computed metrics are available on the first page load.

    The sequence runs once per Streamlit session and is skipped entirely
    when the application is in sandbox or replay mode (``SANDBOX_MODE``).
    """
    if SANDBOX_MODE:
        return
    if st.session_state.get("live_system_initialized"):
        return
    try:
        print("[LIVE] initialize_live_system: starting")
        holdings = expand_wave_holdings()
        prices_pivot = fetch_prices_for_holdings(holdings)
        generate_full_snapshot(holdings, prices_pivot)
        snap_df = pd.read_csv(LIVE_SNAPSHOT_PATH) if LIVE_SNAPSHOT_PATH.exists() else None
        queue_startup_governance_decisions(snap_df)

        # Holdings evaluation pipeline
        from helpers.holding_intelligence import (
            evaluate_holdings as _init_eval_holdings,
            get_holdings_summary as _init_holdings_summary,
        )
        _init_holdings = _init_eval_holdings(DATA_PREFIX)
        st.session_state["holdings_evaluation"] = _init_holdings
        st.session_state["holdings_summary"] = _init_holdings_summary(_init_holdings)
        print(f"[LIVE] initialize_live_system: evaluated {len(_init_holdings)} holdings")

        # Strategy optimization scoring pipeline
        from helpers.strategy_security_optimizer import (
            evaluate_strategy_fit as _init_eval_fit,
            evaluate_replacement_candidates as _init_eval_upgrades,
            generate_strategy_observations as _init_strategy_obs,
            get_strategy_fit_summary as _init_fit_summary,
        )
        _init_fit = _init_eval_fit(_init_holdings)
        _init_upgrades = _init_eval_upgrades(_init_fit)
        _init_obs = _init_strategy_obs(_init_fit, _init_upgrades)
        st.session_state["strategy_fit"] = _init_fit
        st.session_state["strategy_fit_summary"] = _init_fit_summary(_init_fit)
        st.session_state["strategy_observations"] = _init_obs
        print(f"[LIVE] initialize_live_system: strategy fit scored {len(_init_fit)} entries")

        st.session_state["live_system_initialized"] = True
        print("[LIVE] initialize_live_system: complete")
    except Exception as e:
        print(f"[LIVE] initialize_live_system error: {e}")
        st.session_state["live_system_initialized"] = True


initialize_live_system()

snapshot_df, attrib_df, snapshot_error = load_snapshot()
if snapshot_error:
    print(f"[SNAPSHOT] load_snapshot: error - {snapshot_error}")
else:
    rows = len(snapshot_df) if snapshot_df is not None else 0
    print(f"[SNAPSHOT] load_snapshot: loaded {rows} rows, attrib={attrib_df is not None}")

# Fail-fast validation for Alpha Intelligence pipeline
if attrib_df is None or attrib_df.empty:
    print("[ALPHA-INTELLIGENCE][ERROR] Attribution dataframe is empty — Alpha Intelligence will have no data. Run build_alpha_attribution_csv.py to rebuild.")
else:
    _attrib_waves = attrib_df["wave"].dropna().unique().tolist() if "wave" in attrib_df.columns else []
    _unknown_count = sum(1 for w in _attrib_waves if w == "UNKNOWN_WAVE")
    if _unknown_count > 0:
        print(f"[ALPHA-INTELLIGENCE][ERROR] {_unknown_count} UNKNOWN_WAVE entries in attribution — wave name resolution failed. Run build_alpha_attribution_csv.py to rebuild.")
    _horizons_present = sorted(attrib_df["horizon"].dropna().unique().tolist()) if "horizon" in attrib_df.columns else []
    for _req_hz in (30, 90, 365):
        if _req_hz not in _horizons_present:
            print(f"[ALPHA-INTELLIGENCE][ERROR] Horizon {_req_hz}D missing from attribution dataframe — Multi-Horizon Alpha Structure will show '-' for this horizon.")
    print(f"[ALPHA-INTELLIGENCE] Attribution validated: {len(_attrib_waves)} waves, horizons={_horizons_present}")

