cycle_state = None
brief_output = None

def _compute_review_signals_for_cycle(snap_df, attr_df, adpt_state):
    signals = []
    if attr_df is None or attr_df.empty:
        return signals

    comp_labels = {}
    for c in ["selection_alpha", "momentum_alpha", "volatility_alpha", "correlation_alpha"]:
        if c in attr_df.columns:
            comp_labels[c] = c.replace("_alpha", "").replace("_", " ").title()

    horizons_available = []
    if "horizon" in attr_df.columns:
        horizons_available = sorted(attr_df["horizon"].dropna().unique().tolist())

    regime_state = adpt_state.get("regime_state", "unknown").lower() if adpt_state else "unknown"

    for comp_col, comp_name in comp_labels.items():
        neg_horizons = []
        for h in horizons_available:
            h_df = attr_df[attr_df["horizon"] == h]
            if h_df.empty:
                continue
            avg = pd.to_numeric(h_df[comp_col], errors="coerce").mean()
            if avg < -0.002:
                neg_horizons.append(h)
        if len(neg_horizons) >= 2:
            signals.append({
                "title": f"{comp_name} - Review Signal",
                "status": "Review Eligible",
                "scope": "Portfolio-level",
            })

    if "wave" in attr_df.columns:
        waves = attr_df["wave"].dropna().unique().tolist()
        for w in waves:
            w_df = attr_df[attr_df["wave"] == w]
            if w_df.empty:
                continue
            neg_comps = []
            for cc, cn in comp_labels.items():
                if cc not in w_df.columns:
                    continue
                w_avg = pd.to_numeric(w_df[cc], errors="coerce").mean()
                if w_avg < -0.005:
                    neg_comps.append(cn)
            if len(neg_comps) >= 2:
                signals.append({
                    "title": f"{w} - Multi-Component Drag",
                    "status": "Review Eligible",
                    "scope": "Wave-level",
                    "wave": w,
                    "component_count": len(neg_comps),
                    "observation": f"{w} exhibits negative attribution across {len(neg_comps)} components, suggesting broad-based structural headwinds.",
                })

    return signals

if daily_cycle_available:
    cycle_state = load_cycle_state()
    cycle_state = reset_if_new_day(cycle_state)
    if not SANDBOX_MODE:
        save_cycle_state(cycle_state)

    _cycle_adaptive = al.load_adaptive_state() if al else {}
    _cycle_signals = _compute_review_signals_for_cycle(snapshot_df, attrib_df, _cycle_adaptive)

    if should_run_morning(cycle_state):
        brief_output = run_cycle("morning", cycle_state, snapshot_df, attrib_df, review_signals=_cycle_signals, adaptive_state=_cycle_adaptive)

    if should_run_midday(cycle_state):
        brief_output = run_cycle("midday", cycle_state, snapshot_df, attrib_df, review_signals=_cycle_signals, adaptive_state=_cycle_adaptive)

    if should_run_close(cycle_state):
        brief_output = run_cycle("close", cycle_state, snapshot_df, attrib_df, review_signals=_cycle_signals, adaptive_state=_cycle_adaptive)

# ===========================
# Intraday Auto-Refresh Logic
# ===========================
import pytz
ET = pytz.timezone("America/New_York")

def is_market_hours():
    """Check if within US market hours (9:30 AM - 4:00 PM ET, weekdays)."""
    now = datetime.now(ET)
    if now.weekday() >= 5:
        return False
    market_open = now.replace(hour=9, minute=30, second=0, microsecond=0)
    market_close = now.replace(hour=16, minute=0, second=0, microsecond=0)
    return market_open <= now <= market_close

def should_refresh_intraday():
    """Check if intraday data needs refresh (stale by > 10 minutes during market hours)."""
    if not is_market_hours():
        return False
    
    snapshot_path = Path(_data_path("data/live_snapshot.csv"))
    if not snapshot_path.exists():
        return True
    
    try:
        import os
        mtime = os.path.getmtime(snapshot_path)
        age_minutes = (datetime.now().timestamp() - mtime) / 60
        return age_minutes > 10
    except:
        return False

def trigger_intraday_refresh():
    """Trigger background intraday refresh if needed."""
    try:
        import subprocess
        subprocess.Popen(["python", "scripts/refresh_intraday_snapshot.py"], 
                        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:
        pass

if should_refresh_intraday():
    trigger_intraday_refresh()

last_refresh_check = datetime.now(ET).strftime("%H:%M ET")

