def render_signal_route_button(wave_name, signal_source, button_key, signal_label=None, compact=False):
    """NOTE 040: Render a clickable signal routing button that navigates to Decision Review & Implementation.
    Sets council_nav_wave and council_nav_source in session state, then triggers tab switch via JS injection.
    signal_source: one of 'executive_snapshot', 'decision_intelligence', 'adaptive_intelligence', 'wave_diagnostics', 'portfolio_state'
    """
    _tooltip = "Route to Decision Review & Implementation tab. Waves operate autonomously - this routes the governance signal for IC review, not execution. Observational only."
    _label = signal_label if signal_label else f"Review in Decision Tab"
    if compact:
        if st.button(f"{_label} →", key=button_key, help=_tooltip):
            st.session_state["council_nav_wave"] = wave_name
            st.session_state["council_nav_source"] = signal_source
            st.session_state["council_nav_diag"] = None
            st.session_state["signal_route_source_tab"] = signal_source
            st.session_state["signal_route_pending"] = True
            st.rerun()
    else:
        _bc1, _bc2 = st.columns([3, 2])
        with _bc2:
            if st.button(f"{_label} →", key=button_key, help=_tooltip):
                st.session_state["council_nav_wave"] = wave_name
                st.session_state["council_nav_source"] = signal_source
                st.session_state["council_nav_diag"] = None
                st.session_state["signal_route_source_tab"] = signal_source
                st.session_state["signal_route_pending"] = True
                st.rerun()

# ===========================
# GLOBAL DUAL-LAYER ALPHA ATTRIBUTION MODEL (NOTE 039)
# LAYER 1 - Sources: Structural Alpha + Signal-Driven Alpha + Human Decision Alpha + External Effects (sum to 100%)
# LAYER 2 - Drivers: Selection Alpha + Momentum Alpha + Volatility Alpha + Regime Alpha + Exposure Alpha (sum to 100%)
# ===========================
def compute_alpha_attribution_global(sdf, adf, wave_filter=None):
    _gaa = {"structural_alpha": 0.0, "signal_alpha": 0.0, "human_decision_alpha": 0.0, "external_effects": 0.0, "total": 0.0}
    _gaa_30 = {"structural_alpha": 0.0, "signal_alpha": 0.0, "human_decision_alpha": 0.0, "external_effects": 0.0, "total": 0.0}
    _gaa_90 = {"structural_alpha": 0.0, "signal_alpha": 0.0, "human_decision_alpha": 0.0, "external_effects": 0.0, "total": 0.0}

    _drv = {"selection": 0.0, "momentum": 0.0, "volatility": 0.0, "regime": 0.0, "exposure": 0.0}
    _drv_30 = {"selection": 0.0, "momentum": 0.0, "volatility": 0.0, "regime": 0.0, "exposure": 0.0}
    _drv_90 = {"selection": 0.0, "momentum": 0.0, "volatility": 0.0, "regime": 0.0, "exposure": 0.0}

    _driver_col_map = {
        "selection": "selection_alpha",
        "momentum": "momentum_alpha",
        "volatility": "volatility_alpha",
        "regime": "regime_alpha",
        "exposure": "exposure_alpha",
    }

    if adf is not None and not adf.empty and "wave" in adf.columns and "horizon" in adf.columns:
        _gadf = adf.copy()
        if wave_filter:
            _gadf = _gadf[_gadf["wave"] == wave_filter]
        _structural_cols = ["selection_alpha", "momentum_alpha", "exposure_alpha"]
        _signal_cols = ["volatility_alpha", "regime_alpha"]
        _external_col = "residual_alpha"

        for _hz, _tgt, _dtgt in [(365, _gaa, _drv), (30, _gaa_30, _drv_30)]:
            _hdf = _gadf[_gadf["horizon"] == _hz]
            if _hdf.empty:
                continue
            for c in _structural_cols:
                if c in _hdf.columns:
                    _tgt["structural_alpha"] += pd.to_numeric(_hdf[c], errors="coerce").sum()
            for c in _signal_cols:
                if c in _hdf.columns:
                    _tgt["signal_alpha"] += pd.to_numeric(_hdf[c], errors="coerce").sum()
            if _external_col in _hdf.columns:
                _tgt["external_effects"] += pd.to_numeric(_hdf[_external_col], errors="coerce").sum()
            for dk, dcol in _driver_col_map.items():
                if dcol in _hdf.columns:
                    _dtgt[dk] += pd.to_numeric(_hdf[dcol], errors="coerce").sum()

        _interp_w = 90.0 / 365.0
        for k in ["structural_alpha", "signal_alpha", "external_effects"]:
            _gaa_90[k] = _gaa_30[k] + (_gaa[k] - _gaa_30[k]) * _interp_w
        for dk in _drv:
            _drv_90[dk] = _drv_30[dk] + (_drv[dk] - _drv_30[dk]) * _interp_w

    _dl_path = Path("data/decision_log.json")
    _gov_path = Path("data/governance_decisions.json")
    _hda_aligned = 0
    _hda_mixed = 0
    _hda_external = 0
    _hda_total = 0
    _hda_positive_ct = 0
    _hda_negative_ct = 0
    _hda_neutral_ct = 0

    def _ingest_decisions(decs):
        for _d in decs:
            if wave_filter and _d.get("wave", "") != wave_filter:
                continue
            # Support both decision_log.json (outcome_30d) and governance_decisions.json (status)
            _o30 = _d.get("outcome_30d", "")
            _status = _d.get("status", "")
            _regime = _d.get("regime_at_decision", "Neutral")
            if _o30 == "Pending" or not _o30:
                # Fall back to governance status when no outcome recorded
                if _status in ("Approved", "Recorded"):
                    _o30 = "Positive"
                elif _status == "Rejected":
                    _o30 = "Negative"
                elif _status:
                    _o30 = "Neutral"
                else:
                    continue
            if not _o30:
                continue
            nonlocal _hda_total, _hda_aligned, _hda_positive_ct, _hda_neutral_ct
            nonlocal _hda_negative_ct, _hda_mixed, _hda_external
            _hda_total += 1
            if _o30 in ("Positive", "Aligned"):
                _hda_aligned += 1
                _hda_positive_ct += 1
            elif _o30 == "Neutral":
                _hda_aligned += 1
                _hda_neutral_ct += 1
            elif _o30 in ("Negative", "Detracted"):
                if _regime and _regime not in ("Neutral", "Normal", ""):
                    _hda_external += 1
                else:
                    _hda_mixed += 1
                _hda_negative_ct += 1
            elif _o30 == "Mixed":
                _hda_mixed += 1
                _hda_neutral_ct += 1

    for _path in (_dl_path, _gov_path):
        if _path.exists():
            try:
                with open(_path, "r") as f:
                    _decs = json.load(f)
                _ingest_decisions(_decs)
            except Exception:
                pass

    _total_alpha_365 = _gaa["structural_alpha"] + _gaa["signal_alpha"] + _gaa["external_effects"]
    if _hda_total > 0 and abs(_total_alpha_365) > 1e-8:
        _hda_net_score = (_hda_positive_ct - _hda_negative_ct + _hda_neutral_ct * 0.1) / _hda_total
        _hda_365 = _total_alpha_365 * 0.05 * _hda_net_score
    else:
        _hda_365 = 0.0
    _hda_30 = _hda_365 * (30.0 / 365.0)
    _hda_90 = _hda_365 * (90.0 / 365.0)

    _gaa["human_decision_alpha"] = _hda_365
    _gaa_30["human_decision_alpha"] = _hda_30
    _gaa_90["human_decision_alpha"] = _hda_90
    for _tgt in [_gaa, _gaa_30, _gaa_90]:
        _tgt["total"] = _tgt["structural_alpha"] + _tgt["signal_alpha"] + _tgt["human_decision_alpha"] + _tgt["external_effects"]

    def _normalize_pct(d):
        _abs_sum = sum(abs(v) for v in d.values())
        if _abs_sum < 1e-9:
            return {k: 0.0 for k in d}
        return {k: abs(v) / _abs_sum for k, v in d.items()}

    _src_norm = _normalize_pct({"structural": _gaa["structural_alpha"], "signal": _gaa["signal_alpha"], "human": _gaa["human_decision_alpha"], "external": _gaa["external_effects"]})
    _src_norm_30 = _normalize_pct({"structural": _gaa_30["structural_alpha"], "signal": _gaa_30["signal_alpha"], "human": _gaa_30["human_decision_alpha"], "external": _gaa_30["external_effects"]})
    _src_norm_90 = _normalize_pct({"structural": _gaa_90["structural_alpha"], "signal": _gaa_90["signal_alpha"], "human": _gaa_90["human_decision_alpha"], "external": _gaa_90["external_effects"]})

    _drv_norm = _normalize_pct(_drv)
    _drv_norm_30 = _normalize_pct(_drv_30)
    _drv_norm_90 = _normalize_pct(_drv_90)

    return {
        "365": _gaa, "30": _gaa_30, "90": _gaa_90,
        "decision_stats": {"aligned": _hda_aligned, "mixed": _hda_mixed, "external": _hda_external, "total": _hda_total},
        "sources_pct": {"365": _src_norm, "30": _src_norm_30, "90": _src_norm_90},
        "drivers": {"365": _drv, "30": _drv_30, "90": _drv_90},
        "drivers_pct": {"365": _drv_norm, "30": _drv_norm_30, "90": _drv_norm_90},
    }

alpha_attribution_global = compute_alpha_attribution_global(snapshot_df, attrib_df)

# ===========================
# CONFIRMATION STACK (NOTE 033)
# Unified confirmation panel - observational only
# Uses real system diagnostics, no synthetic signals
# ===========================
def compute_confirmation_stack(sdf, adf, adaptive_state_path="data/adaptive_state.json", wave_filter=None):
    stack = {}

    _cs_adaptive = {}
    try:
        _cs_ap = Path(adaptive_state_path)
        if _cs_ap.exists():
            with open(_cs_ap, "r") as f:
                _cs_adaptive = json.load(f)
    except Exception:
        pass

    _cs_wdf = sdf
    if wave_filter and sdf is not None and not sdf.empty:
        _name_col = "display_name" if "display_name" in sdf.columns else "wave_name"
        _cs_wdf = sdf[sdf[_name_col] == wave_filter]
        if _cs_wdf.empty:
            _cs_wdf = sdf

    _cs_adf = adf
    if wave_filter and adf is not None and not adf.empty:
        _a_col = "wave" if "wave" in adf.columns else "wave_name" if "wave_name" in adf.columns else None
        if _a_col:
            _cs_adf = adf[adf[_a_col] == wave_filter]
            if _cs_adf.empty:
                _cs_adf = adf

    _cs_is_single = wave_filter is not None and _cs_wdf is not None and len(_cs_wdf) == 1

    # 1) Cross-Horizon Alignment - from wave alpha signs across horizons
    _cs_ch_status = "Mixed"
    if _cs_is_single:
        _cs_row = _cs_wdf.iloc[0]
        _cs_a1d = pd.to_numeric(_cs_row.get("alpha_1d"), errors="coerce") if _cs_row.get("alpha_1d") is not None else float('nan')
        _cs_a30 = pd.to_numeric(_cs_row.get("alpha_30d"), errors="coerce") if _cs_row.get("alpha_30d") is not None else float('nan')
        _cs_a60 = pd.to_numeric(_cs_row.get("alpha_60d"), errors="coerce") if _cs_row.get("alpha_60d") is not None else float('nan')
        _cs_a365 = pd.to_numeric(_cs_row.get("alpha_365d"), errors="coerce") if _cs_row.get("alpha_365d") is not None else float('nan')
        _cs_alphas = [v for v in [_cs_a1d, _cs_a30, _cs_a60, _cs_a365] if pd.notna(v)]
        if len(_cs_alphas) >= 2:
            _cs_pos = sum(1 for v in _cs_alphas if v > 0)
            _cs_neg = sum(1 for v in _cs_alphas if v < 0)
            if _cs_pos == len(_cs_alphas) or _cs_neg == len(_cs_alphas):
                _cs_ch_status = "Aligned"
            elif _cs_pos >= len(_cs_alphas) * 0.7 or _cs_neg >= len(_cs_alphas) * 0.7:
                _cs_ch_status = "Mixed"
            else:
                _cs_ch_status = "Conflicted"
    else:
        _cs_ch_raw = _cs_adaptive.get("cross_horizon_alignment", {})
        _cs_ch_avg = None
        if isinstance(_cs_ch_raw, dict):
            _cs_ch_vals = [v for v in _cs_ch_raw.values() if isinstance(v, (int, float))]
            if _cs_ch_vals:
                _cs_ch_avg = sum(_cs_ch_vals) / len(_cs_ch_vals)
        elif isinstance(_cs_ch_raw, (int, float)):
            _cs_ch_avg = float(_cs_ch_raw)
        if _cs_ch_avg is None and _cs_wdf is not None and not _cs_wdf.empty:
            _agree_count = 0
            _total_count = 0
            if "alpha_30d" in _cs_wdf.columns and "alpha_365d" in _cs_wdf.columns:
                for _, _r in _cs_wdf.iterrows():
                    _a30 = pd.to_numeric(_r.get("alpha_30d"), errors="coerce") if _r.get("alpha_30d") is not None else float('nan')
                    _a365 = pd.to_numeric(_r.get("alpha_365d"), errors="coerce") if _r.get("alpha_365d") is not None else float('nan')
                    if pd.notna(_a30) and pd.notna(_a365):
                        _total_count += 1
                        if (_a30 > 0) == (_a365 > 0):
                            _agree_count += 1
                if _total_count > 0:
                    _cs_ch_avg = _agree_count / _total_count
        if _cs_ch_avg is not None:
            if _cs_ch_avg > 0.7:
                _cs_ch_status = "Aligned"
            elif _cs_ch_avg > 0.4:
                _cs_ch_status = "Mixed"
            else:
                _cs_ch_status = "Conflicted"
    stack["Cross-Horizon Alignment"] = _cs_ch_status

    # 2) Market Participation / Breadth - single wave: return magnitude; portfolio: breadth ratio
    _cs_bp_status = "Neutral"
    if _cs_is_single:
        _cs_row = _cs_wdf.iloc[0]
        _cs_r30 = pd.to_numeric(_cs_row.get("return_30d"), errors="coerce") if _cs_row.get("return_30d") is not None else float('nan')
        _cs_bm30 = pd.to_numeric(_cs_row.get("benchmark_return_30d"), errors="coerce") if _cs_row.get("benchmark_return_30d") is not None else float('nan')
        if pd.notna(_cs_r30) and pd.notna(_cs_bm30) and _cs_bm30 != 0:
            _cs_part_ratio = _cs_r30 / abs(_cs_bm30) if abs(_cs_bm30) > 1e-6 else 1.0
            if _cs_part_ratio > 1.2:
                _cs_bp_status = "Expanding"
            elif _cs_part_ratio < 0.5:
                _cs_bp_status = "Deteriorating"
            else:
                _cs_bp_status = "Neutral"
        elif pd.notna(_cs_r30):
            if _cs_r30 > 0.02:
                _cs_bp_status = "Expanding"
            elif _cs_r30 < -0.02:
                _cs_bp_status = "Deteriorating"
    else:
        if _cs_wdf is not None and not _cs_wdf.empty and "alpha_30d" in _cs_wdf.columns:
            _cs_a30_vals = pd.to_numeric(_cs_wdf["alpha_30d"], errors="coerce").dropna()
            if len(_cs_a30_vals) > 0:
                _cs_pos_pct = (_cs_a30_vals > 0).sum() / len(_cs_a30_vals)
                if _cs_pos_pct >= 0.65:
                    _cs_bp_status = "Expanding"
                elif _cs_pos_pct <= 0.35:
                    _cs_bp_status = "Deteriorating"
    stack["Market Participation"] = _cs_bp_status

    # 3) Volatility Regime Context - from adaptive volatility regime + wave benchmark vol
    _cs_vol_status = "Moderate"
    if _cs_is_single and "benchmark_volatility_30d" in _cs_wdf.columns:
        _cs_bv_val = pd.to_numeric(_cs_wdf.iloc[0].get("benchmark_volatility_30d"), errors="coerce")
        if pd.notna(_cs_bv_val):
            if _cs_bv_val > 0.25:
                _cs_vol_status = "Elevated"
            elif _cs_bv_val < 0.12:
                _cs_vol_status = "Low"
            else:
                _cs_vol_status = "Moderate"
        else:
            _cs_pm = _cs_adaptive.get("pattern_memory", {})
            _cs_vol_current = _cs_pm.get("volatility_regime", {}).get("current")
            if _cs_vol_current is not None:
                if _cs_vol_current > 0.25:
                    _cs_vol_status = "Elevated"
                elif _cs_vol_current < 0.12:
                    _cs_vol_status = "Low"
    else:
        _cs_pm = _cs_adaptive.get("pattern_memory", {})
        _cs_vol_regime = _cs_pm.get("volatility_regime", {})
        _cs_vol_current = _cs_vol_regime.get("current")
        if _cs_vol_current is not None:
            if _cs_vol_current > 0.25:
                _cs_vol_status = "Elevated"
            elif _cs_vol_current < 0.12:
                _cs_vol_status = "Low"
        elif _cs_wdf is not None and not _cs_wdf.empty and "benchmark_volatility_30d" in _cs_wdf.columns:
            _cs_bvol = pd.to_numeric(_cs_wdf["benchmark_volatility_30d"], errors="coerce").dropna()
            if len(_cs_bvol) > 0:
                _cs_bvol_avg = _cs_bvol.mean()
                if _cs_bvol_avg > 0.25:
                    _cs_vol_status = "Elevated"
                elif _cs_bvol_avg < 0.12:
                    _cs_vol_status = "Low"
    stack["Volatility Context"] = _cs_vol_status

    # 4) Signal Persistence - single wave: multi-horizon alpha consistency; portfolio: regime trends
    _cs_sp_status = "Mixed"
    if _cs_is_single:
        _cs_row = _cs_wdf.iloc[0]
        _cs_a1d_sp = pd.to_numeric(_cs_row.get("alpha_1d"), errors="coerce") if _cs_row.get("alpha_1d") is not None else float('nan')
        _cs_a30_sp = pd.to_numeric(_cs_row.get("alpha_30d"), errors="coerce") if _cs_row.get("alpha_30d") is not None else float('nan')
        _cs_a60_sp = pd.to_numeric(_cs_row.get("alpha_60d"), errors="coerce") if _cs_row.get("alpha_60d") is not None else float('nan')
        _cs_a365_sp = pd.to_numeric(_cs_row.get("alpha_365d"), errors="coerce") if _cs_row.get("alpha_365d") is not None else float('nan')
        _cs_sp_vals = [v for v in [_cs_a1d_sp, _cs_a30_sp, _cs_a60_sp, _cs_a365_sp] if pd.notna(v)]
        if len(_cs_sp_vals) >= 2:
            _cs_sp_pos = sum(1 for v in _cs_sp_vals if v > 0)
            if _cs_sp_pos == len(_cs_sp_vals) or _cs_sp_pos == 0:
                _cs_sp_status = "Stable"
            elif _cs_sp_pos >= len(_cs_sp_vals) - 1 or _cs_sp_pos <= 1:
                _cs_sp_status = "Mixed"
            else:
                _cs_sp_status = "Unstable"
        _cs_attrib_horizons = []
        if _cs_adf is not None and not _cs_adf.empty and "horizon" in _cs_adf.columns and "total_alpha" in _cs_adf.columns:
            for _, _ar in _cs_adf.iterrows():
                _ta = pd.to_numeric(_ar.get("total_alpha"), errors="coerce")
                if pd.notna(_ta):
                    _cs_attrib_horizons.append(_ta)
        if len(_cs_attrib_horizons) >= 2:
            _cs_at_pos = sum(1 for v in _cs_attrib_horizons if v > 0)
            if _cs_at_pos == len(_cs_attrib_horizons) or _cs_at_pos == 0:
                pass
            else:
                _cs_sp_status = "Mixed"
    else:
        _cs_pm = _cs_adaptive.get("pattern_memory", {})
        _cs_vol_regime = _cs_pm.get("volatility_regime", {})
        _cs_vol_trend = _cs_vol_regime.get("trend", "")
        _cs_mom_trend = _cs_pm.get("momentum_regime", {}).get("trend", "")
        _cs_stable_count = 0
        _cs_unstable_count = 0
        for _t in [_cs_vol_trend, _cs_mom_trend]:
            if _t in ("stable", "neutral"):
                _cs_stable_count += 1
            elif _t in ("volatile", "unstable", "deteriorating"):
                _cs_unstable_count += 1
        if _cs_wdf is not None and not _cs_wdf.empty and "alpha_30d" in _cs_wdf.columns and "alpha_365d" in _cs_wdf.columns:
            _cs_sign_agree = 0
            _cs_sign_total = 0
            for _, _r in _cs_wdf.iterrows():
                _a30v = pd.to_numeric(_r.get("alpha_30d"), errors="coerce") if _r.get("alpha_30d") is not None else float('nan')
                _a365v = pd.to_numeric(_r.get("alpha_365d"), errors="coerce") if _r.get("alpha_365d") is not None else float('nan')
                if pd.notna(_a30v) and pd.notna(_a365v):
                    _cs_sign_total += 1
                    if (_a30v > 0) == (_a365v > 0):
                        _cs_sign_agree += 1
            if _cs_sign_total > 0:
                if _cs_sign_agree / _cs_sign_total > 0.7:
                    _cs_stable_count += 1
                elif _cs_sign_agree / _cs_sign_total < 0.4:
                    _cs_unstable_count += 1
        if _cs_stable_count >= 2 and _cs_unstable_count == 0:
            _cs_sp_status = "Stable"
        elif _cs_unstable_count >= 2:
            _cs_sp_status = "Unstable"
    stack["Signal Persistence"] = _cs_sp_status

    # 5) Relative Strength Leadership - single wave: wave alpha vs portfolio median; portfolio: breadth
    _cs_rs_status = "Concentrated"
    if _cs_is_single:
        _cs_row = _cs_wdf.iloc[0]
        _cs_wa365 = pd.to_numeric(_cs_row.get("alpha_365d"), errors="coerce") if _cs_row.get("alpha_365d") is not None else float('nan')
        if pd.notna(_cs_wa365) and sdf is not None and not sdf.empty and "alpha_365d" in sdf.columns:
            _cs_all_a365 = pd.to_numeric(sdf["alpha_365d"], errors="coerce").dropna()
            if len(_cs_all_a365) > 0:
                _cs_median = _cs_all_a365.median()
                _cs_p75 = _cs_all_a365.quantile(0.75)
                if _cs_wa365 >= _cs_p75:
                    _cs_rs_status = "Broad"
                elif _cs_wa365 >= _cs_median:
                    _cs_rs_status = "Concentrated"
                else:
                    _cs_rs_status = "Weak"
        elif pd.notna(_cs_wa365):
            if _cs_wa365 > 0.02:
                _cs_rs_status = "Broad"
            elif _cs_wa365 < -0.02:
                _cs_rs_status = "Weak"
    else:
        if _cs_wdf is not None and not _cs_wdf.empty and "alpha_365d" in _cs_wdf.columns:
            _cs_a365_vals = pd.to_numeric(_cs_wdf["alpha_365d"], errors="coerce").dropna()
            if len(_cs_a365_vals) >= 3:
                _cs_pos_alpha = (_cs_a365_vals > 0).sum()
                _cs_pos_ratio = _cs_pos_alpha / len(_cs_a365_vals)
                if _cs_pos_ratio >= 0.6:
                    _cs_rs_status = "Broad"
                elif _cs_pos_ratio >= 0.35:
                    _cs_rs_status = "Concentrated"
                else:
                    _cs_rs_status = "Weak"
    stack["Relative Strength"] = _cs_rs_status

    # 6) Liquidity & Volume Support - from wave drawdown + benchmark vol
    _cs_lq_status = "Neutral"
    if _cs_is_single:
        _cs_row = _cs_wdf.iloc[0]
        _cs_dd = pd.to_numeric(_cs_row.get("drawdown_30d"), errors="coerce") if _cs_row.get("drawdown_30d") is not None else 0.0
        _cs_bv = pd.to_numeric(_cs_row.get("benchmark_volatility_30d"), errors="coerce") if _cs_row.get("benchmark_volatility_30d") is not None else 0.0
        _cs_dd = _cs_dd if pd.notna(_cs_dd) else 0.0
        _cs_bv = _cs_bv if pd.notna(_cs_bv) else 0.0
        if abs(_cs_dd) > 0.05 or _cs_bv > 0.25:
            _cs_lq_status = "Stressed"
        elif abs(_cs_dd) < 0.02 and _cs_bv < 0.15:
            _cs_lq_status = "Supportive"
    else:
        if _cs_wdf is not None and not _cs_wdf.empty:
            _cs_dd_stressed = 0
            _cs_dd_total = 0
            if "drawdown_30d" in _cs_wdf.columns:
                _cs_dd_vals = pd.to_numeric(_cs_wdf["drawdown_30d"], errors="coerce").dropna()
                _cs_dd_total = len(_cs_dd_vals)
                _cs_dd_stressed = (abs(_cs_dd_vals) > 0.05).sum()
            _cs_bvol_stress = False
            if "benchmark_volatility_30d" in _cs_wdf.columns:
                _cs_bv = pd.to_numeric(_cs_wdf["benchmark_volatility_30d"], errors="coerce").dropna()
                if len(_cs_bv) > 0 and _cs_bv.mean() > 0.25:
                    _cs_bvol_stress = True
            if _cs_dd_total > 0:
                _cs_dd_pct = _cs_dd_stressed / _cs_dd_total
                if _cs_dd_pct > 0.4 or _cs_bvol_stress:
                    _cs_lq_status = "Stressed"
                elif _cs_dd_pct < 0.15 and not _cs_bvol_stress:
                    _cs_lq_status = "Supportive"
    stack["Liquidity Support"] = _cs_lq_status

    return stack


def render_decision_outcome_chart(decision, snap_df):
    """NOTE 031 - Decision Outcome Chart (Institutional, Observational).
    Shows portfolio vs benchmark performance normalized to 0% at decision date.
    Uses canonical data only - discrete horizon returns from live_snapshot.csv.
    No synthetic data, no simulation, no execution logic."""
    import altair as alt
    from datetime import datetime, timedelta

    dec_date_str = decision.get("date", "")
    dec_wave = decision.get("wave", "")

    if not dec_date_str:
        st.markdown('<div style="color:#6B7280;font-size:12px;padding:16px;text-align:center;">Decision date not recorded in governance data.</div>', unsafe_allow_html=True)
        return

    try:
        dec_date = datetime.strptime(dec_date_str, "%Y-%m-%d")
    except Exception:
        st.markdown('<div style="color:#6B7280;font-size:12px;padding:16px;text-align:center;">Invalid decision date format.</div>', unsafe_allow_html=True)
        return

    wave_row = None
    if snap_df is not None and not snap_df.empty and dec_wave:
        dn_col = "display_name" if "display_name" in snap_df.columns else "wave_name"
        matches = snap_df[snap_df[dn_col] == dec_wave]
        if not matches.empty:
            wave_row = matches.iloc[0]

    if wave_row is None:
        st.markdown('<div style="color:#6B7280;font-size:12px;padding:16px;text-align:center;">Insufficient canonical data recorded for this governance decision. No matching wave found in live snapshot.</div>', unsafe_allow_html=True)
        return

    today = datetime.now()
    days_since = (today - dec_date).days

    if days_since < 1:
        st.markdown('<div style="color:#6B7280;font-size:12px;padding:16px;text-align:center;">Decision date is today or in the future. Outcome data not yet available.</div>', unsafe_allow_html=True)
        return

    port_1d = float(wave_row.get("return_1d", 0) or 0)
    port_30d = float(wave_row.get("return_30d", 0) or 0)
    port_60d = float(wave_row.get("return_60d", 0) or 0)
    port_365d = float(wave_row.get("return_365d", 0) or 0)
    alpha_1d = float(wave_row.get("alpha_1d", 0) or 0)
    alpha_30d = float(wave_row.get("alpha_30d", 0) or 0)
    alpha_60d = float(wave_row.get("alpha_60d", 0) or 0)
    alpha_365d = float(wave_row.get("alpha_365d", 0) or 0)
    bench_1d = port_1d - alpha_1d
    bench_30d = port_30d - alpha_30d
    bench_60d = port_60d - alpha_60d
    bench_365d = port_365d - alpha_365d

    horizons = [
        (0, 0.0, 0.0, "Decision Date"),
        (1, port_1d, bench_1d, "1D"),
        (30, port_30d, bench_30d, "30D"),
        (60, port_60d, bench_60d, "60D"),
        (365, port_365d, bench_365d, "365D"),
    ]

    chart_data = []
    horizons_used = []
    for h_days, p_ret, b_ret, label in horizons:
        if h_days <= days_since:
            h_date = dec_date + timedelta(days=h_days)
            chart_data.append({"Date": h_date.strftime("%Y-%m-%d"), "Series": "Portfolio", "Return (%)": round(p_ret * 100, 2), "Horizon": label})
            chart_data.append({"Date": h_date.strftime("%Y-%m-%d"), "Series": "Benchmark", "Return (%)": round(b_ret * 100, 2), "Horizon": label})
            horizons_used.append(label)

    if len(horizons_used) < 2:
        st.markdown('<div style="color:#6B7280;font-size:12px;padding:16px;text-align:center;">Insufficient elapsed time since decision date for outcome comparison.</div>', unsafe_allow_html=True)
        return

    chart_df = pd.DataFrame(chart_data)

    color_scale = alt.Scale(
        domain=["Portfolio", "Benchmark"],
        range=["#3A6FF7", "#6B7280"]
    )

    line = alt.Chart(chart_df).mark_line(strokeWidth=2, point=alt.OverlayMarkDef(size=50)).encode(
        x=alt.X("Date:T", axis=alt.Axis(
            labelColor="#6B7280", titleColor="#6B7280",
            labelAngle=-45, format="%b %d", title="",
            gridColor="rgba(255,255,255,0.03)"
        )),
        y=alt.Y("Return (%):Q", axis=alt.Axis(
            labelColor="#6B7280", titleColor="#6B7280",
            title="Cumulative Return (%)",
            gridColor="rgba(255,255,255,0.05)"
        )),
        color=alt.Color("Series:N", scale=color_scale, legend=alt.Legend(
            orient="top", labelColor="#9EA3AE", titleColor="#9EA3AE",
            labelFontSize=10, symbolStrokeWidth=2
        )),
        strokeDash=alt.condition(
            alt.datum.Series == "Benchmark",
            alt.value([4, 3]),
            alt.value([0])
        )
    )

    labels = alt.Chart(chart_df[chart_df["Series"] == "Portfolio"]).mark_text(
        align="center", dy=-14, fontSize=9, color="#9EA3AE"
    ).encode(
        x=alt.X("Date:T"),
        y=alt.Y("Return (%):Q"),
        text=alt.Text("Horizon:N")
    )

    chart = (line + labels).properties(
        title=alt.Title(
            text="Decision Outcome vs Benchmark",
            subtitle=f"Performance normalized to decision date ({dec_date_str}) · {dec_wave or 'Portfolio'} · Observed canonical horizons: {', '.join(horizons_used)}",
            color="#E5E5E5",
            subtitleColor="#6B7280",
            fontSize=14,
            subtitleFontSize=10
        ),
        height=280
    ).configure(
        background="#0D1117"
    ).configure_view(
        strokeWidth=0
    )

    st.altair_chart(chart, width="stretch")

    st.markdown("""<div style="color:#4B5563;font-size:9px;margin:-8px 0 8px 0;font-style:italic;text-align:center;line-height:1.5;">
This chart shows observed portfolio performance relative to its benchmark from the decision date forward. It is informational, observational, and does not simulate alternative outcomes. Data points represent canonical return horizons (1D, 30D, 60D, 365D) from live_snapshot.csv.
</div>""", unsafe_allow_html=True)


def render_pending_decisions(decision_data, panel_key="default"):
    """NOTE 013: Pending Governance Decisions & Actions panel. Reusable across tabs."""
    from datetime import datetime, timedelta
    now = datetime.now()

    pending_states = {"Awaiting Approval", "Under Review", "Pending", "Monitoring", "Deferred", "Active"}
    pending = []
    for d in (decision_data or []):
        status = d.get("status", "")
        approval = d.get("approval_status", "")
        impl = d.get("implementation_state", "")
        outcome = d.get("outcome_30d", "")
        if status in pending_states or approval == "Pending" or impl == "Pending Execution":
            pending.append(d)
        elif status == "Recorded" and outcome == "Pending":
            pending.append(d)

    st.markdown('<div style="border-bottom: 1px solid #2A2F3A; margin: 16px 0 12px 0;"></div>', unsafe_allow_html=True)
    st.markdown("""<div style="margin-bottom: 4px;">
<span style="color: #E5E5E5; font-size: 13px; font-weight: 700;">Pending Governance Decisions & Actions</span>
</div>""", unsafe_allow_html=True)
    st.markdown('<div style="color: #6B7280; font-size: 10px; margin: -4px 0 12px 0;">Governance decisions requiring attention · Observational · Non-executing</div>', unsafe_allow_html=True)

    # Pre-compute wave-level review count for logic alignment (Institutional Fallback)
    _wave_review_count = 0
    if snapshot_df is not None and not snapshot_df.empty:
        for _, _row in snapshot_df.iterrows():
            _wa30 = float(_row.get("alpha_30d", 0) or 0)
            _wa60 = float(_row.get("alpha_60d", 0) or 0)
            _wa365 = float(_row.get("alpha_365d", 0) or 0)
            _wbvol = float(_row.get("benchmark_volatility_30d", 0) or 0)
            _w_regime_aligned = True
            if _wbvol > 0.20 and _wa30 < -0.01: _w_regime_aligned = False
            if _wbvol < 0.10 and _wa30 < 0: _w_regime_aligned = False
            _w_neg_count = sum(1 for a in [_wa30, _wa60, _wa365] if a < -0.005)
            if _w_neg_count >= 2 or (not _w_regime_aligned and _wa30 < -0.01):
                _wave_review_count += 1

    if not pending:
        if _wave_review_count > 0:
            st.markdown(f"""<div style="background: #1C1F26; border: 1px solid #2A2F3A; border-left: 4px solid #F5C451; padding: 18px 16px; border-radius: 0 6px 6px 0; margin-bottom: 12px;">
<div style="color: #E5E5E5; font-size: 13px; font-weight: 700;">{_wave_review_count} Waves Flagged for Review</div>
<div style="color: #9EA3AE; font-size: 11px; margin-top: 4px; font-style: italic;">No formal decision objects have been created yet. Wave-level diagnostics indicate monitoring or review conditions.</div>
<div style="margin-top: 10px; font-size: 11px; color: #6B7280;">Review the Executive Snapshot or Wave Health Snapshot for specific diagnostic details.</div>
</div>""", unsafe_allow_html=True)
        else:
            st.markdown("""<div style="background: #1C1F26; border: 1px solid #2A2F3A; padding: 24px; border-radius: 6px; text-align: center; margin-bottom: 12px;">
<div style="color: #9EA3AE; font-size: 13px; font-weight: 600;">No pending decisions at this time.</div>
<div style="color: #6B7280; font-size: 11px; margin-top: 6px;">All strategies are operating within current governance parameters.</div>
</div>""", unsafe_allow_html=True)
    else:
        for di, dec in enumerate(pending):
            dec_id = dec.get("id", f"DEC-{di}")
            dec_wave = dec.get("wave", "Portfolio")
            dec_type_raw = dec.get("decision_type", dec.get("event_type", "-"))
            dec_type = "Override Decision" if dec_type_raw and "override" in str(dec_type_raw).lower() else "Governance Decision" if dec_type_raw and dec_type_raw != "-" else dec_type_raw
            dec_actor = dec.get("actor", "-")
            dec_status = dec.get("status", "Unknown")
            dec_approval = dec.get("approval_status", "")
            dec_impl = dec.get("implementation_state", "")
            dec_date = dec.get("date", "-")
            dec_rationale = dec.get("rationale", dec.get("context_notes", ""))
            dec_outcome = dec.get("outcome_30d", "")

            if dec_status == "Awaiting Approval" or dec_approval == "Pending":
                badge_label = "Awaiting Approval"
                badge_color = "#F59E0B"
            elif dec_status == "Under Review":
                badge_label = "Pending Review"
                badge_color = "#3B82F6"
            elif dec_status == "Monitoring" or dec_status == "Active":
                badge_label = "Monitoring"
                badge_color = "#8B5CF6"
            elif dec_status == "Deferred":
                badge_label = "Deferred"
                badge_color = "#6B7280"
            elif dec_outcome == "Pending" and dec_impl == "Completed":
                badge_label = "Outcome Window Open"
                badge_color = "#10B981"
            else:
                badge_label = dec_status
                badge_color = "#9EA3AE"

            upcoming_note = ""
            try:
                dec_dt = datetime.strptime(dec_date, "%Y-%m-%d")
                days_since = (now - dec_dt).days
                if dec_outcome == "Pending" and days_since >= 0:
                    days_to_30 = 30 - days_since
                    if days_to_30 > 0:
                        upcoming_note = f"30D outcome window completes in {days_to_30} days"
                    elif days_to_30 <= 0:
                        upcoming_note = "30D outcome window has elapsed - review eligible"
                if dec_approval == "Pending" and not upcoming_note:
                    upcoming_note = "Awaiting IC approval"
                if dec_status == "Monitoring" and not upcoming_note:
                    upcoming_note = "Monitoring due to active signals"
                if dec_status == "Under Review" and not upcoming_note:
                    upcoming_note = "Under governance review"
            except Exception:
                pass

            rationale_html = f'<div style="color: #9EA3AE; font-size: 11px; line-height: 1.5; margin-top: 8px; font-style: italic;">{dec_rationale}</div>' if dec_rationale else ""
            upcoming_html = f'<div style="color: #6B7280; font-size: 10px; margin-top: 6px;">{upcoming_note}</div>' if upcoming_note else ""

            st.markdown(f"""<div style="background: #1C1F26; border: 1px solid #2A2F3A; border-left: 4px solid {badge_color}; padding: 14px 16px; border-radius: 0 6px 6px 0; margin-bottom: 8px;">
<div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; flex-wrap: wrap;">
<div>
<div style="color: #E5E5E5; font-size: 13px; font-weight: 700;">{dec_id}</div>
<div style="color: #9EA3AE; font-size: 11px; margin-top: 2px;">{dec_wave}</div>
</div>
<div style="background: {badge_color}22; border: 1px solid {badge_color}55; padding: 3px 10px; border-radius: 4px;">
<span style="color: {badge_color}; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;">{badge_label}</span>
</div>
</div>
<div style="display: flex; flex-wrap: wrap; gap: 16px; margin-top: 10px;">
<div style="min-width: 100px;"><span style="color: #6B7280; font-size: 9px; text-transform: uppercase;">Type</span><br><span style="color: #C0C4CC; font-size: 11px; word-break: break-word; white-space: normal;">{dec_type}</span></div>
<div style="min-width: 100px;"><span style="color: #6B7280; font-size: 9px; text-transform: uppercase;">Actor</span><br><span style="color: #C0C4CC; font-size: 11px; word-break: break-word; white-space: normal;">{dec_actor}</span></div>
<div style="min-width: 80px;"><span style="color: #6B7280; font-size: 9px; text-transform: uppercase;">Initiated</span><br><span style="color: #C0C4CC; font-size: 11px;">{dec_date}</span></div>
</div>
{rationale_html}
{upcoming_html}
</div>""", unsafe_allow_html=True)

    st.markdown("""<div style="background: #151A22; padding: 8px 16px; border-radius: 6px; margin: 8px 0 0 0; border: 1px solid #2A2F3A;">
<div style="color: #4B5563; font-size: 9px; text-align: center; line-height: 1.6;">
This section provides an observational view of decisions awaiting review, approval, or outcome evaluation. It does not trigger execution or automate actions.
</div>
</div>""", unsafe_allow_html=True)


def render_confirmation_stack(sdf, adf, wave_filter=None):
    _cs_stack = compute_confirmation_stack(sdf, adf, wave_filter=wave_filter)
    _cs_positive = {"Aligned", "Expanding", "Stable", "Broad", "Supportive", "Low"}
    _cs_neutral = {"Mixed", "Neutral", "Moderate", "Concentrated"}
    _cs_negative = {"Conflicted", "Deteriorating", "Elevated", "Unstable", "Weak", "Stressed"}

    def _cs_color(status):
        if status in _cs_positive:
            return "#4A9F6E"
        elif status in _cs_negative:
            return "#C45B5B"
        return "#8A8F9A"

    _cs_labels = ["Cross-Horizon Alignment", "Market Participation", "Volatility Context",
                  "Signal Persistence", "Relative Strength", "Liquidity Support"]

    _cs_pos_ct = sum(1 for l in _cs_labels if _cs_stack.get(l, "") in _cs_positive)
    _cs_neg_ct = sum(1 for l in _cs_labels if _cs_stack.get(l, "") in _cs_negative)
    _cs_neu_ct = sum(1 for l in _cs_labels if _cs_stack.get(l, "") in _cs_neutral)

    _cs_parts = []
    _cs_ch_val = _cs_stack.get("Cross-Horizon Alignment", "Mixed")
    if _cs_ch_val == "Aligned":
        _cs_parts.append("aligned across horizons")
    elif _cs_ch_val == "Conflicted":
        _cs_parts.append("showing cross-horizon conflict")
    else:
        _cs_parts.append("mixed across horizons")

    _cs_sp_val = _cs_stack.get("Signal Persistence", "Mixed")
    if _cs_sp_val == "Stable":
        _cs_parts.append("with stable signal persistence")
    elif _cs_sp_val == "Unstable":
        _cs_parts.append("with unstable signal persistence")
    else:
        _cs_parts.append("with mixed signal persistence")

    _cs_vol_val = _cs_stack.get("Volatility Context", "Moderate")
    _cs_parts.append(f"and {_cs_vol_val.lower()} volatility conditions")

    _cs_orientation = f"Confirmation signals are {' '.join(_cs_parts[:1])}, {', '.join(_cs_parts[1:])}."

    _cs_title = "Confirmation Stack"
    if wave_filter:
        _cs_title = f"Confirmation Stack - {wave_filter}"

    _cs_html = '<div style="background:#151A22;border:1px solid #2A2F3A;border-radius:8px;padding:16px 18px;margin:8px 0 16px 0;">'
    _cs_html += '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:4px;">'
    _cs_html += f'<span style="color:#E5E5E5;font-size:13px;font-weight:600;letter-spacing:0.02em;">{_cs_title}</span>'
    _cs_html += f'<span style="color:#6B7280;font-size:10px;font-style:italic;">{_cs_pos_ct} positive · {_cs_neu_ct} neutral · {_cs_neg_ct} negative</span>'
    _cs_html += '</div>'

    _cs_html += f'<div style="color:#9EA3AE;font-size:11px;line-height:1.6;margin-bottom:14px;padding:8px 12px;background:#0D1117;border-left:3px solid #3A6FF7;border-radius:4px;">{_cs_orientation}</div>'

    _cs_html += '<table style="width:100%;border-collapse:collapse;">'
    _cs_html += '<tr style="border-bottom:1px solid #2A2F3A;">'
    _cs_html += '<th style="text-align:left;padding:6px 10px;color:#6B7280;font-size:10px;text-transform:uppercase;letter-spacing:0.06em;font-weight:600;">Component</th>'
    _cs_html += '<th style="text-align:right;padding:6px 10px;color:#6B7280;font-size:10px;text-transform:uppercase;letter-spacing:0.06em;font-weight:600;">Status</th>'
    _cs_html += '</tr>'

    for _cs_lbl in _cs_labels:
        _cs_val = _cs_stack.get(_cs_lbl, "-")
        _cs_c = _cs_color(_cs_val)
        _cs_dot = f'<span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:{_cs_c};margin-right:8px;vertical-align:middle;"></span>'
        _cs_html += f'<tr style="border-bottom:1px solid #1C2029;">'
        _cs_html += f'<td style="padding:8px 10px;color:#C0C4CC;font-size:12px;">{_cs_lbl}</td>'
        _cs_html += f'<td style="padding:8px 10px;text-align:right;font-size:12px;font-weight:600;color:{_cs_c};">{_cs_dot}{_cs_val}</td>'
        _cs_html += '</tr>'

    _cs_html += '</table></div>'
    st.markdown(_cs_html, unsafe_allow_html=True)

    with st.expander("Confirmation Stack Detail", expanded=False):
        _csd_items = [
            ("Cross-Horizon Alignment", _cs_stack.get("Cross-Horizon Alignment", "Mixed"),
             "Measures directional agreement across 30D, 60D, and 365D alpha horizons.",
             "When horizons agree on direction, conviction is higher. Divergence indicates transitional conditions.",
             "Aligned: All horizons confirm direction. Mixed: Short and long horizons diverge. Divergent: No clear agreement."),
            ("Market Participation", _cs_stack.get("Market Participation", "Mixed"),
             "Assesses breadth of positive alpha contribution across portfolio waves.",
             "Broad participation indicates systematic strength. Concentrated participation may indicate idiosyncratic drivers.",
             "Expanding: Broad-based alpha. Concentrated: Alpha driven by few waves. Narrow: Limited participation."),
            ("Volatility Context", _cs_stack.get("Volatility Context", "Mixed"),
             "Current volatility regime relative to benchmark and historical norms.",
             "Elevated volatility may reduce confidence in near-term signals. Low volatility supports signal reliability.",
             "Low: Below historical norms. Moderate: Within expected range. Elevated: Above historical norms."),
            ("Signal Persistence", _cs_stack.get("Signal Persistence", "Mixed"),
             "Stability and consistency of alpha signals across multiple time periods.",
             "Persistent signals indicate structural drivers. Transient signals may reflect noise or regime transitions.",
             "Persistent: Stable across periods. Intermittent: Some variation observed. Transient: Unstable signals."),
            ("Relative Strength", _cs_stack.get("Relative Strength", "Mixed"),
             "Wave-level alpha strength relative to portfolio median and benchmark context.",
             "Leadership indicates above-median performance. Lagging may warrant review but not necessarily action.",
             "Leading: Above portfolio median. Neutral: Near median. Lagging: Below portfolio median."),
            ("Liquidity Support", _cs_stack.get("Liquidity Support", "Mixed"),
             "Assessment of portfolio liquidity conditions and market depth context.",
             "Supportive liquidity facilitates implementation. Constrained liquidity requires additional caution.",
             "Supportive: Normal market depth. Moderate: Some constraints observed. Constrained: Limited liquidity."),
        ]
        for _csd_label, _csd_val, _csd_driver, _csd_context, _csd_classification in _csd_items:
            _csd_color = "#48BB78" if _csd_val in ("Aligned", "Expanding", "Stable", "Broad", "Supportive", "Low", "Persistent", "Leading") else ("#F59E0B" if _csd_val in ("Mixed", "Neutral", "Moderate", "Concentrated", "Intermittent") else "#EF4444")
            st.markdown(f"""<div style="background: #151A22; border: 1px solid #2A2F3A; border-radius: 6px; padding: 12px 16px; margin-bottom: 8px;">
<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
<span style="color: #E5E7EB; font-size: 12px; font-weight: 600;">{_csd_label}</span>
<span style="color: {_csd_color}; font-size: 11px; font-weight: 600;">{_csd_val}</span>
</div>
<div style="color: #9EA3AE; font-size: 11px; margin-bottom: 4px;"><strong>Driver:</strong> {_csd_driver}</div>
<div style="color: #9EA3AE; font-size: 11px; margin-bottom: 4px;"><strong>Context:</strong> {_csd_context}</div>
<div style="color: #9EA3AE; font-size: 11px; margin-bottom: 4px;"><strong>Classification:</strong> {_csd_classification}</div>
<div style="color: #4B5563; font-size: 10px; font-style: italic; margin-top: 4px;">This indicator is observational and does not recommend specific actions.</div>
</div>""", unsafe_allow_html=True)


