def _load_ic_decisions():
    ic_decision_log_path = "data/decision_log.json"
    ic_decisions = []
    if os.path.exists(ic_decision_log_path):
        try:
            with open(ic_decision_log_path, "r") as f:
                ic_decisions = json.load(f)
        except Exception:
            ic_decisions = []
    return ic_decisions

def render_ic_context_vs_outcome_matrix():
    ic_decisions = _load_ic_decisions()
    st.markdown("**Context vs Outcome Matrix**")
    st.markdown("""<div class="waves-caption" style="margin: 4px 0 12px 0;">
Outcomes by regime context at time of decision · Read-only
</div>""", unsafe_allow_html=True)
    if ic_decisions and len(ic_decisions) > 0:
        regime_contexts = {}
        for d in ic_decisions:
            context = d.get("context", d.get("regime_context", "Unknown"))
            if not context or context == "-":
                context = "Unknown"
            if context not in regime_contexts:
                regime_contexts[context] = {"count": 0, "outcome_30d": [], "outcome_90d": []}
            regime_contexts[context]["count"] += 1
            o30 = d.get("outcome_30d", "")
            o90 = d.get("outcome_90d", "")
            if o30 and o30 != "Pending" and o30 != "-":
                try:
                    regime_contexts[context]["outcome_30d"].append(float(str(o30).replace("%", "").replace("+", "")))
                except:
                    pass
            if o90 and o90 != "Pending" and o90 != "-":
                try:
                    regime_contexts[context]["outcome_90d"].append(float(str(o90).replace("%", "").replace("+", "")))
                except:
                    pass
        context_html = """<div style="background: #151A22; border-radius: 6px; padding: 12px; margin: 8px 0; overflow-x: auto;">
<table style="width: 100%; border-collapse: collapse; font-size: 11px;">
<thead>
<tr style="border-bottom: 1px solid rgba(255,255,255,0.1);">
<th style="text-align: left; padding: 8px; color: #6B7280; font-weight: 500;">Regime Context</th>
<th style="text-align: center; padding: 8px; color: #6B7280; font-weight: 500;">Decisions</th>
<th style="text-align: center; padding: 8px; color: #6B7280; font-weight: 500;">Avg 30D Outcome</th>
<th style="text-align: center; padding: 8px; color: #6B7280; font-weight: 500;">Avg 90D Outcome</th>
</tr>
</thead>
<tbody>"""
        for context, data in regime_contexts.items():
            avg_30d = "Pending"
            avg_90d = "Pending"
            if data["outcome_30d"]:
                avg_30d = f"{sum(data['outcome_30d'])/len(data['outcome_30d']):.1f}%"
            if data["outcome_90d"]:
                avg_90d = f"{sum(data['outcome_90d'])/len(data['outcome_90d']):.1f}%"
            context_html += f"""<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
<td style="padding: 8px; color: #E5E5E5;">{context}</td>
<td style="text-align: center; padding: 8px; color: #C8CCD4;">{data['count']}</td>
<td style="text-align: center; padding: 8px; color: #9AA0AC;">{avg_30d}</td>
<td style="text-align: center; padding: 8px; color: #9AA0AC;">{avg_90d}</td>
</tr>"""
        context_html += """</tbody></table></div>"""
        st.markdown(context_html, unsafe_allow_html=True)
    else:
        st.markdown("""<div style="background: #151A22; border-radius: 6px; padding: 20px; text-align: center; color: #6B7280; font-size: 12px; margin: 8px 0;">
Regime-conditioned outcomes will appear as contextual data accumulates.
</div>""", unsafe_allow_html=True)

def render_ic_multi_horizon_consistency():
    ic_decisions = _load_ic_decisions()
    st.markdown("**Multi-Horizon Decision Consistency**")
    st.markdown("""<div class="waves-caption" style="margin: 4px 0 12px 0;">
Outcomes observed across standard decision horizons · Read-only · Observational
</div>""", unsafe_allow_html=True)
    if ic_decisions and len(ic_decisions) > 0:
        horizon_data = {"30D": [], "60D": [], "90D": [], "365D": []}
        for d in ic_decisions:
            o30 = d.get("outcome_30d", "")
            o60 = d.get("outcome_60d", "")
            o90 = d.get("outcome_90d", "")
            o365 = d.get("outcome_365d", "")
            for key, val in [("30D", o30), ("60D", o60), ("90D", o90), ("365D", o365)]:
                if val and val not in ["Pending", "-", ""]:
                    try:
                        horizon_data[key].append(float(str(val).replace("%", "").replace("+", "")))
                    except:
                        pass
        def get_avg_outcome(vals):
            if not vals:
                return "Pending"
            avg = sum(vals) / len(vals)
            return f"{avg:+.1f}%"
        def get_regime_context(vals):
            if not vals:
                return "Insufficient data"
            avg = sum(vals) / len(vals)
            if avg > 1.0:
                return "Constructive"
            elif avg < -1.0:
                return "Challenging"
            else:
                return "Mixed"
        def get_consistency(h30, h60, h90, h365):
            available = [h for h in [h30, h60, h90, h365] if h]
            if len(available) < 2:
                return "Insufficient Data"
            avgs = [sum(h)/len(h) for h in available]
            if len(avgs) < 2:
                return "Insufficient Data"
            spread = max(avgs) - min(avgs)
            short_avg = sum(h30)/len(h30) if h30 else None
            long_avg = sum(h365)/len(h365) if h365 else None
            if short_avg is not None and long_avg is not None:
                if abs(short_avg - long_avg) > 3.0:
                    return "Regime-Sensitive"
            if spread < 2.0:
                return "Stable"
            else:
                return "Mixed"
        consistency_overall = get_consistency(
            horizon_data["30D"], horizon_data["60D"],
            horizon_data["90D"], horizon_data["365D"]
        )
        horizon_table = """<div style="overflow-x: auto; margin: 8px 0;">
<table style="width: 100%; border-collapse: collapse; font-size: 11px; background: #151A22; border-radius: 6px;">
<thead>
<tr style="border-bottom: 1px solid #2A2F3A;">
<th style="text-align: left; padding: 10px; color: #9AA0AC; font-weight: 500;">Horizon</th>
<th style="text-align: center; padding: 10px; color: #9AA0AC; font-weight: 500;">Avg Outcome</th>
<th style="text-align: center; padding: 10px; color: #9AA0AC; font-weight: 500;">Regime Context</th>
<th style="text-align: center; padding: 10px; color: #9AA0AC; font-weight: 500;">Consistency</th>
</tr>
</thead>
<tbody>"""
        for horizon in ["30D", "60D", "90D", "365D"]:
            avg_out = get_avg_outcome(horizon_data[horizon])
            regime_ctx = get_regime_context(horizon_data[horizon])
            consistency_status = consistency_overall
            horizon_table += f"""<tr style="border-bottom: 1px solid #1E2530;">
<td style="padding: 10px; color: #E5E5E5; font-weight: 500;">{horizon}</td>
<td style="text-align: center; padding: 10px; color: #C8CCD4;">{avg_out}</td>
<td style="text-align: center; padding: 10px; color: #9AA0AC;">{regime_ctx}</td>
<td style="text-align: center; padding: 10px; color: #9AA0AC;">{consistency_status}</td>
</tr>"""
        horizon_table += """</tbody></table></div>"""
        st.markdown(horizon_table, unsafe_allow_html=True)
        if consistency_overall == "Stable":
            synthesis = "Outcomes remained consistent across all observed decision horizons."
        elif consistency_overall == "Regime-Sensitive":
            synthesis = "Short-term outcomes were regime-sensitive, while longer-horizon results remained stable."
        elif consistency_overall == "Mixed":
            synthesis = "Short-term variation was observed, with stabilization over quarterly and annual horizons."
        else:
            synthesis = "Insufficient multi-horizon history for stability assessment."
        st.markdown(f"""<div style="background: #12132A; border-left: 2px solid #3B82F6; padding: 12px 16px; margin: 12px 0; font-size: 11px; color: #C8CCD4; font-style: italic;">
{synthesis}
</div>""", unsafe_allow_html=True)
    else:
        st.markdown("""<div style="background: #151A22; border-radius: 6px; padding: 20px; text-align: center; color: #6B7280; font-size: 12px; margin: 8px 0;">
No governance decisions recorded during the current observation window.
</div>""", unsafe_allow_html=True)
    st.markdown("""<div style="color: #6B7280; font-size: 10px; margin: 12px 0 16px 0; font-style: italic;">
This multi-horizon view is observational and intended for governance context only. It does not rank managers, assign scores, or recommend actions.
</div>""", unsafe_allow_html=True)

def render_ic_decision_stability():
    ic_decisions = _load_ic_decisions()
    st.markdown("**Decision Stability Indicator**")
    if ic_decisions and len(ic_decisions) > 0:
        all_outcomes = []
        for d in ic_decisions:
            o30 = d.get("outcome_30d", "")
            if o30 and o30 != "Pending" and o30 != "-":
                try:
                    all_outcomes.append(float(str(o30).replace("%", "").replace("+", "")))
                except:
                    pass
        if len(all_outcomes) >= 3:
            outcome_std = np.std(all_outcomes) if len(all_outcomes) > 1 else 0
            if outcome_std < 2.0:
                stability_status = "High"
                stability_desc = "outcomes have remained consistent across observed decision contexts."
                stability_color = "#10B981"
            elif outcome_std < 5.0:
                stability_status = "Moderate"
                stability_desc = "outcomes show some dispersion across different regimes."
                stability_color = "#F59E0B"
            else:
                stability_status = "Review Eligible"
                stability_desc = "outcomes have varied significantly across contexts."
                stability_color = "#EF4444"
            st.markdown(f"""<div style="background: #151A22; border-radius: 6px; padding: 14px; margin: 8px 0; border-left: 3px solid {stability_color};">
<div style="color: #E5E5E5; font-size: 13px;">
<strong>Decision Outcome Stability:</strong> <span style="color: {stability_color};">{stability_status}</span> - {stability_desc}
</div>
</div>""", unsafe_allow_html=True)
        else:
            st.markdown("""<div style="background: #151A22; border-radius: 6px; padding: 14px; margin: 8px 0; color: #6B7280; font-size: 12px;">
Insufficient outcome data to assess decision stability. Indicator will update as outcomes accumulate.
</div>""", unsafe_allow_html=True)
    else:
        st.markdown("""<div style="background: #151A22; border-radius: 6px; padding: 14px; margin: 8px 0; color: #6B7280; font-size: 12px;">
No governance decisions recorded during the current observation window.
</div>""", unsafe_allow_html=True)

def render_ic_primary_attention():
    ic_decisions = _load_ic_decisions()
    st.markdown("**Primary Area of Attention**")
    if ic_decisions and len(ic_decisions) > 0:
        attention_areas = []
        vol_count = 0
        regime_mixed = 0
        concentration_flag = False
        for d in ic_decisions:
            category = d.get("category", d.get("type", "")).lower()
            if "volatility" in category or "vol" in category:
                vol_count += 1
            if "concentration" in category:
                concentration_flag = True
            context = d.get("context", d.get("regime_context", "")).lower()
            o30 = d.get("outcome_30d", "")
            if context and "high" in context or "compressed" in context:
                if o30 and o30 not in ["Pending", "-"]:
                    try:
                        val = float(str(o30).replace("%", "").replace("+", ""))
                        if val < 0:
                            regime_mixed += 1
                    except:
                        pass
        if vol_count >= 2:
            attention_signal = "Primary area of attention: volatility management behavior under compressed regimes."
        elif regime_mixed >= 2:
            attention_signal = "Primary area of attention: mixed short-term outcomes across high-volatility contexts."
        elif concentration_flag:
            attention_signal = "Primary area of attention: concentration positioning under current market conditions."
        else:
            attention_signal = "No persistent areas of concern detected across major components."
    else:
        attention_signal = "Insufficient decision history for attention assessment."
    st.markdown(f"""<div style="background: #12132A; border-left: 2px solid #F59E0B; padding: 12px 16px; margin: 8px 0; font-size: 12px; color: #E5E5E5;">
{attention_signal}
</div>""", unsafe_allow_html=True)
    st.markdown("""<div style="color: #6B7280; font-size: 10px; margin: 8px 0 16px 0; font-style: italic;">
Orientation signal for committee awareness. Observational only.
</div>""", unsafe_allow_html=True)

