# ===========================
# Helper Renderers
# ===========================
def render_metric_row(metrics_dict, label_prefix="", intraday_label=None, has_intraday_data=True):
    """
    Render a row of metrics using Streamlit columns.
    
    For intraday metrics:
    - If has_intraday_data is False (no data exists at all), show "-"
    - If has_intraday_data is True, show the value even if it's zero (true zero movement)
    
    For 365D metrics:
    - If no data exists, show "Insufficient history" instead of dash
    
    This ensures:
    - After market close with no session data: show "-"  
    - True zero movement during/after session: show "0.00%"
    """
    cols = st.columns(len(metrics_dict))
    for col, (label, val) in zip(cols, metrics_dict.items()):
        with col:
            # Check if this is an intraday metric with no data at all
            is_intraday = intraday_label is not None and label == intraday_label
            is_365d = label == "365D"
            
            if pd.isna(val) or val is None:
                if is_365d:
                    display = "Insufficient history"
                else:
                    display = "-"
            elif is_intraday and not has_intraday_data:
                # No intraday data exists at all - show "-"
                display = "-"
            else:
                # Show value (including true zero movement)
                display = f"{val*100:.2f}%"
            
            st.metric(
                label=f"{label_prefix}{label}",
                value=display,
                delta=None,
            )


def compute_portfolio_metrics(df, return_cols, alpha_cols):
    """
    Compute equal-weighted portfolio metrics.
    Handles NaN values explicitly.
    """
    portfolio_returns = {}
    portfolio_alphas = {}

    for label, col in return_cols.items():
        if col in df.columns:
            valid_values = df[col].dropna()
            if len(valid_values) > 0:
                portfolio_returns[label] = valid_values.mean()
            else:
                portfolio_returns[label] = None
        else:
            portfolio_returns[label] = None

    for label, col in alpha_cols.items():
        if col in df.columns:
            valid_values = df[col].dropna()
            if len(valid_values) > 0:
                portfolio_alphas[label] = valid_values.mean()
            else:
                portfolio_alphas[label] = None
        else:
            portfolio_alphas[label] = None

    return portfolio_returns, portfolio_alphas


def compute_attribution_from_summary(attrib_df, horizon):
    """
    Compute portfolio-level attribution from the attribution summary.
    Returns aggregated components for the selected horizon.
    
    The attribution components should sum to total_alpha:
    total_alpha = selection_alpha + momentum_alpha + volatility_alpha + 
                  regime_alpha + exposure_alpha + residual_alpha
    """
    if attrib_df is None or attrib_df.empty:
        return None

    # Map horizon labels to numeric values
    horizon_map = {"30D": 30, "60D": 60, "365D": 365}
    horizon_val = horizon_map.get(horizon)
    
    if horizon_val is None:
        return None

    # Filter for the selected horizon
    horizon_data = attrib_df[attrib_df["horizon"] == horizon_val]
    
    if horizon_data.empty:
        return None

    # Component columns in the attribution summary
    component_cols = [
        "selection_alpha",
        "momentum_alpha", 
        "volatility_alpha",
        "regime_alpha",
        "exposure_alpha",
        "residual_alpha"
    ]

    result = {
        "total_alpha": None,
        "selection_alpha": None,
        "momentum_alpha": None,
        "volatility_alpha": None,
        "regime_alpha": None,
        "exposure_alpha": None,
        "residual_alpha": None,
    }

    # Compute equal-weighted portfolio averages for each component
    for col in component_cols:
        if col in horizon_data.columns:
            valid_values = pd.to_numeric(horizon_data[col], errors='coerce').dropna()
            if len(valid_values) > 0:
                result[col] = valid_values.mean()

    # Compute total_alpha from the data
    if "total_alpha" in horizon_data.columns:
        valid_values = pd.to_numeric(horizon_data["total_alpha"], errors='coerce').dropna()
        if len(valid_values) > 0:
            result["total_alpha"] = valid_values.mean()
    else:
        # If total_alpha not in data, sum the components
        component_sum = 0.0
        has_components = False
        for col in component_cols:
            if result[col] is not None:
                component_sum += result[col]
                has_components = True
        if has_components:
            result["total_alpha"] = component_sum

    return result


INTRADAY_STATE_PATH = DATA_DIR / "intraday_attribution_state.json"


def load_intraday_state():
    """
    Load persisted intraday attribution state from last valid session.
    Validates schema and freshness before returning.
    """
    if INTRADAY_STATE_PATH.exists():
        try:
            import json
            from datetime import datetime, timedelta
            
            with open(INTRADAY_STATE_PATH, "r") as f:
                state = json.load(f)
            
            # Validate required fields exist
            required_fields = ["total_alpha", "selection_alpha", "momentum_alpha", 
                             "volatility_alpha", "regime_alpha", "exposure_alpha", "residual_alpha"]
            if not all(field in state for field in required_fields):
                return None
            
            # Mark as from persisted state for display purposes
            state["from_persisted"] = True
            
            # Check if saved_at exists and is within reasonable timeframe (7 days)
            if "saved_at" in state:
                try:
                    saved_time = datetime.fromisoformat(state["saved_at"])
                    if datetime.now() - saved_time > timedelta(days=7):
                        # Stale data - don't use
                        return None
                except Exception:
                    pass
            
            return state
        except Exception:
            pass
    return None


def save_intraday_state(state):
    """Persist intraday attribution state for use after market close."""
    try:
        import json
        from datetime import datetime
        state["saved_at"] = datetime.now().isoformat()
        with open(INTRADAY_STATE_PATH, "w") as f:
            json.dump(state, f, indent=2)
    except Exception:
        pass


def compute_intraday_attribution(snapshot_df):
    """
    Compute intraday attribution components INDEPENDENTLY from wave-level data.
    Each component uses distinct wave characteristics - never derived from a single scalar.
    
    PERSISTENCE: When valid intraday data exists, state is saved. After market close
    or when intraday is zero/missing, last valid state is loaded and returned.
    
    Component Computation Logic:
    - Selection: Cross-sectional dispersion of wave-level alpha
    - Momentum: Correlation of intraday alpha with 30D trend
    - Volatility: Intraday return volatility impact 
    - Regime: Alignment with long-term (365D) alpha direction
    - Exposure: Portfolio breadth and concentration effects
    - Net Effect: Combined secondary and interaction effects not captured by primary components
    """
    if snapshot_df is None or snapshot_df.empty:
        # No data - try to load persisted state
        return load_intraday_state()
    
    # Get intraday alpha from snapshot
    if "alpha_1d" not in snapshot_df.columns:
        return load_intraday_state()
    
    valid_intraday = snapshot_df["alpha_1d"].dropna()
    if len(valid_intraday) == 0:
        return load_intraday_state()
    
    # Total intraday alpha is the equal-weighted mean
    total_intraday_alpha = valid_intraday.mean()
    
    # IMPORTANT: Valid zeros ARE real data - do not replace with persisted state
    # Only use persistence when data is actually MISSING (handled above with dropna)
    # The fact that we have valid_intraday values means we have real data
    # Zero movement is a valid market condition that should be displayed
    
    # Track if this is a new valid session for saving purposes
    intraday_returns = snapshot_df["return_1d"].dropna() if "return_1d" in snapshot_df.columns else pd.Series()
    has_meaningful_activity = len(valid_intraday) > 0 and (
        (valid_intraday.abs() > 1e-10).any() or 
        (len(intraday_returns) > 0 and (intraday_returns.abs() > 1e-10).any())
    )
    
    result = {
        "total_alpha": total_intraday_alpha,
        "selection_alpha": None,
        "momentum_alpha": None,
        "volatility_alpha": None,
        "regime_alpha": None,
        "exposure_alpha": None,
        "residual_alpha": None,
    }
    
    # CRITICAL: Do NOT zero out components just because total is small
    # Each component is computed independently from wave-level data
    # Even if total alpha is ~0, components can be non-zero (offsetting effects)
    
    # ---- 1) SELECTION ALPHA ----
    # Measures cross-sectional dispersion and wave selection quality
    # Uses wave-level alpha variance as the signal
    wave_alphas = snapshot_df["alpha_1d"].dropna()
    if len(wave_alphas) > 1:
        # Selection contribution based on realized dispersion vs expected
        alpha_std = wave_alphas.std()
        alpha_skew = wave_alphas.skew() if len(wave_alphas) > 2 else 0
        
        # Positive skew with positive mean = good selection
        # Negative skew with positive mean = concentrated winners
        selection_quality = alpha_std * (1 + 0.3 * np.sign(alpha_skew))
        
        # Scale by direction: positive if alpha dispersion adds value
        if wave_alphas.mean() >= 0:
            result["selection_alpha"] = selection_quality * 0.4
        else:
            result["selection_alpha"] = -selection_quality * 0.4
    else:
        result["selection_alpha"] = 0.0
    
    # ---- 2) MOMENTUM ALPHA ----
    # Measures alignment of intraday alpha with 30D trend
    # Independent signal: correlation between wave rankings today vs 30D
    if "alpha_30d" in snapshot_df.columns:
        alpha_30d = snapshot_df["alpha_30d"].dropna()
        
        # Get overlapping waves for both horizons
        common_idx = wave_alphas.index.intersection(alpha_30d.index)
        if len(common_idx) > 2:
            intraday_subset = wave_alphas.loc[common_idx]
            alpha_30d_subset = alpha_30d.loc[common_idx]
            
            # Correlation measures trend persistence
            trend_corr = intraday_subset.corr(alpha_30d_subset)
            if pd.notna(trend_corr):
                # Positive correlation = momentum is working
                # Negative correlation = mean reversion
                momentum_contribution = trend_corr * abs(intraday_subset.mean()) * 0.25
                result["momentum_alpha"] = momentum_contribution
            else:
                result["momentum_alpha"] = 0.0
        else:
            # Fallback: use 30D alpha mean as momentum signal
            mom_signal = alpha_30d.mean() if len(alpha_30d) > 0 else 0
            result["momentum_alpha"] = np.sign(mom_signal) * abs(total_intraday_alpha) * 0.15
    else:
        result["momentum_alpha"] = 0.0
    
    # ---- 3) VOLATILITY ALPHA ----
    # Measures impact of intraday return dispersion
    # High vol with positive alpha = risky gains; high vol with negative = drawdown
    if "return_1d" in snapshot_df.columns:
        returns = snapshot_df["return_1d"].dropna()
        if len(returns) > 1:
            return_vol = returns.std()
            return_mean = returns.mean()
            
            # Volatility drag: high vol typically hurts risk-adjusted returns
            # But can amplify gains in trending markets
            if return_mean > 0:
                # Positive returns: vol is acceptable cost
                result["volatility_alpha"] = -return_vol * 0.5
            else:
                # Negative returns: vol compounds losses
                result["volatility_alpha"] = -return_vol * 0.8
        else:
            result["volatility_alpha"] = 0.0
    else:
        result["volatility_alpha"] = 0.0
    
    # ---- 4) REGIME ALPHA ----
    # Measures alignment with long-term (365D) structural alpha
    # Independent signal: whether today's moves align with long-term winners
    if "alpha_365d" in snapshot_df.columns:
        alpha_365d = snapshot_df["alpha_365d"].dropna()
        
        common_idx = wave_alphas.index.intersection(alpha_365d.index)
        if len(common_idx) > 2:
            intraday_subset = wave_alphas.loc[common_idx]
            alpha_365d_subset = alpha_365d.loc[common_idx]
            
            # Check if long-term winners are also winning today
            lt_winners = alpha_365d_subset > 0
            today_winners = intraday_subset > 0
            
            # Agreement rate as regime signal
            agreement_rate = (lt_winners == today_winners).mean()
            
            # Regime contribution based on alignment
            regime_signal = (agreement_rate - 0.5) * 2  # Scale to [-1, 1]
            result["regime_alpha"] = regime_signal * abs(total_intraday_alpha) * 0.2
        else:
            # Fallback: simple sign alignment
            lt_mean = alpha_365d.mean() if len(alpha_365d) > 0 else 0
            alignment = np.sign(lt_mean) == np.sign(total_intraday_alpha)
            result["regime_alpha"] = abs(total_intraday_alpha) * (0.15 if alignment else 0.05)
    else:
        result["regime_alpha"] = 0.0
    
    # ---- 5) EXPOSURE ALPHA ----
    # Measures portfolio breadth and concentration effects
    # Independent signal: number of contributing waves and their balance
    n_waves = len(valid_intraday)
    n_positive = (valid_intraday > 0).sum()
    n_negative = (valid_intraday < 0).sum()
    
    # Breadth factor: more waves = better diversification
    breadth_factor = min(n_waves / 25, 1.0)
    
    # Balance factor: more balanced = exposure is working
    if n_waves > 0:
        balance_ratio = min(n_positive, n_negative) / max(n_positive, n_negative) if max(n_positive, n_negative) > 0 else 0
    else:
        balance_ratio = 0
    
    # Exposure contribution
    exposure_signal = breadth_factor * (1 - 0.3 * balance_ratio)  # Less balanced = more directional exposure
    result["exposure_alpha"] = exposure_signal * total_intraday_alpha * 0.15
    
    # ---- 6) RESIDUAL ALPHA ----
    # Whatever is not explained by the above components
    # Should be small if attribution is working well
    computed_sum = sum(v for v in [
        result["selection_alpha"],
        result["momentum_alpha"],
        result["volatility_alpha"],
        result["regime_alpha"],
        result["exposure_alpha"],
    ] if v is not None)
    
    result["residual_alpha"] = total_intraday_alpha - computed_sum
    
    # PERSIST: Save valid intraday state for use when data is missing
    # Only save when there's meaningful activity (non-zero values)
    # This preserves the last active session's state
    if has_meaningful_activity:
        if not SANDBOX_MODE:
            save_intraday_state(result)
    
    return result


def check_attribution_integrity(components):
    """
    Check if attribution components pass integrity checks.
    Returns (is_valid, warning_message) tuple.
    Flags if >=2 components are numerically identical beyond tolerance.
    """
    if components is None:
        return True, None
    
    tolerance = 1e-6
    component_values = []
    component_names = []
    
    for name in ["selection_alpha", "momentum_alpha", "volatility_alpha", 
                 "regime_alpha", "exposure_alpha", "residual_alpha"]:
        val = components.get(name)
        if val is not None:
            component_values.append(val)
            component_names.append(name)
    
    if len(component_values) < 2:
        return True, None
    
    # Check for identical values
    identical_pairs = []
    for i in range(len(component_values)):
        for j in range(i + 1, len(component_values)):
            if abs(component_values[i] - component_values[j]) < tolerance:
                if abs(component_values[i]) > tolerance:  # Ignore both being zero
                    identical_pairs.append((component_names[i], component_names[j]))
    
    if len(identical_pairs) >= 1:
        pairs_str = ", ".join([f"{p[0]} = {p[1]}" for p in identical_pairs[:2]])
        return False, f"Integrity warning: Identical component values detected ({pairs_str})"
    
    return True, None


# ===========================
# NOTE 047 - Enterprise Decision Integration Layer (Phase 1)
# System-of-Record Foundation - Read-Only, Observational, Non-Executing
# ===========================

def build_standardized_decision(raw_decision, snapshot_df=None, attrib_df=None, adaptive_state=None):
    """
    NOTE 047 - Build a standardized decision object from raw decision_log entry.
    Enriches with attribution, regime, and cross-horizon context from real data.
    Returns None if raw_decision is invalid.
    """
    if not raw_decision or not isinstance(raw_decision, dict):
        return None

    dec_id = raw_decision.get("id", raw_decision.get("decision_id", ""))
    wave_name = raw_decision.get("wave", "")
    dec_type = raw_decision.get("type", raw_decision.get("decision_type", ""))
    status = raw_decision.get("status", raw_decision.get("approval_status", ""))
    timestamp = raw_decision.get("timestamp", "")
    actor = raw_decision.get("approved_by", raw_decision.get("actor", ""))
    regime_ctx = raw_decision.get("regime_at_decision", raw_decision.get("regime_context", ""))
    rationale = raw_decision.get("rationale", raw_decision.get("action", ""))
    source = raw_decision.get("source", "system")

    primary_driver = ""
    attribution_snapshot = {}
    cross_horizon_ctx = {}
    confidence_level = "Moderate"
    signal_summary = rationale

    if attrib_df is not None and not attrib_df.empty and wave_name:
        try:
            wave_attrib = pd.DataFrame()
            if "wave" in attrib_df.columns:
                wave_attrib = attrib_df[attrib_df["wave"].str.lower() == wave_name.lower()]
                if wave_attrib.empty:
                    wn_tokens = [t.lower() for t in wave_name.split() if t.lower() not in ("wave", "the", "institutional")]
                    for token in wn_tokens[:2]:
                        wave_attrib = attrib_df[attrib_df["wave"].str.lower().str.contains(token, na=False)]
                        if not wave_attrib.empty:
                            break
            if not wave_attrib.empty:
                h30 = wave_attrib[wave_attrib["horizon"] == 30] if "horizon" in wave_attrib.columns else wave_attrib
                if not h30.empty:
                    row = h30.iloc[0]
                    components = {}
                    for comp in ["selection_alpha", "momentum_alpha", "volatility_alpha", "regime_alpha"]:
                        if comp in row.index and pd.notna(row[comp]):
                            components[comp] = float(row[comp])
                    if components:
                        attribution_snapshot = components
                        best_comp = max(components, key=lambda k: abs(components[k]))
                        primary_driver = best_comp.replace("_alpha", "").replace("_", " ").title()
        except Exception:
            pass

    if snapshot_df is not None and not snapshot_df.empty and wave_name:
        try:
            wave_snap = pd.DataFrame()
            if "display_name" in snapshot_df.columns:
                wave_snap = snapshot_df[snapshot_df["display_name"].str.lower() == wave_name.lower()]
                if wave_snap.empty:
                    wn_tokens = [t.lower() for t in wave_name.split() if t.lower() not in ("wave", "the", "institutional")]
                    for token in wn_tokens[:2]:
                        wave_snap = snapshot_df[snapshot_df["display_name"].str.lower().str.contains(token, na=False)]
                        if not wave_snap.empty:
                            break
            if not wave_snap.empty:
                row = wave_snap.iloc[0]
                for hz, col in [("30d", "alpha_30d"), ("60d", "alpha_60d"), ("365d", "alpha_365d")]:
                    if col in row.index and pd.notna(row[col]):
                        cross_horizon_ctx[hz] = float(row[col])
        except Exception:
            pass

    if adaptive_state and isinstance(adaptive_state, dict):
        learning_grade = adaptive_state.get("learning_grade", "")
        if learning_grade:
            confidence_level = "High" if learning_grade in ("A", "A-", "B+") else ("Low" if learning_grade in ("D", "D-", "F") else "Moderate")

    decision_outcome = raw_decision.get("decision_outcome", raw_decision.get("outcome", None))

    return {
        "decision_id": dec_id,
        "wave_name": wave_name,
        "decision_type": dec_type,
        "source": source,
        "actor": actor or "",
        "timestamp": timestamp,
        "status": status,
        "primary_driver": primary_driver,
        "regime_context": regime_ctx,
        "confidence_level": confidence_level,
        "signal_summary": signal_summary,
        "attribution_snapshot": attribution_snapshot,
        "cross_horizon_context": cross_horizon_ctx,
        "decision_outcome": decision_outcome
    }


def decision_api_get_all(snapshot_df=None, attrib_df=None, adaptive_state=None):
    """
    NOTE 047 - Internal Decision API: GET /decisions
    Returns list of all standardized decision objects from decision_log.json.
    Read-only. No execution logic.
    """
    decisions = []
    try:
        if os.path.exists("data/decision_log.json"):
            with open("data/decision_log.json", "r") as f:
                raw_decisions = json.load(f)
            for rd in raw_decisions:
                std = build_standardized_decision(rd, snapshot_df, attrib_df, adaptive_state)
                if std:
                    decisions.append(std)
    except Exception:
        pass
    return decisions


def decision_api_get_by_id(decision_id, snapshot_df=None, attrib_df=None, adaptive_state=None):
    """
    NOTE 047 - Internal Decision API: GET /decisions/{decision_id}
    Returns single standardized decision object. Read-only.
    """
    try:
        if os.path.exists("data/decision_log.json"):
            with open("data/decision_log.json", "r") as f:
                raw_decisions = json.load(f)
            for rd in raw_decisions:
                rid = rd.get("id", rd.get("decision_id", ""))
                if rid == decision_id:
                    return build_standardized_decision(rd, snapshot_df, attrib_df, adaptive_state)
    except Exception:
        pass
    return None


def decision_api_wave_context(wave_name, snapshot_df=None, attrib_df=None, adaptive_state=None):
    """
    NOTE 047 - Internal Decision API: GET /waves/{wave_name}/decision_context
    Returns decision context for a specific wave. Read-only.
    """
    context = {
        "wave_name": wave_name,
        "active_decisions": [],
        "status_summary": {},
        "drivers": [],
        "review_signals": [],
        "outcome_summary": ""
    }
    all_decisions = decision_api_get_all(snapshot_df, attrib_df, adaptive_state)
    wave_decisions = [d for d in all_decisions if d["wave_name"] and wave_name.lower() in d["wave_name"].lower()]

    status_counts = {}
    for d in wave_decisions:
        s = d["status"]
        status_counts[s] = status_counts.get(s, 0) + 1
        if d["primary_driver"]:
            context["drivers"].append(d["primary_driver"])

    context["active_decisions"] = wave_decisions
    context["status_summary"] = status_counts

    outcomes_present = [d for d in wave_decisions if d.get("decision_outcome")]
    if outcomes_present:
        context["outcome_summary"] = f"{len(outcomes_present)} of {len(wave_decisions)} decisions have recorded outcomes."
    else:
        context["outcome_summary"] = "No outcome data recorded for this wave."

    return context


def decision_api_portfolio_state(snapshot_df=None, attrib_df=None, adaptive_state=None):
    """
    NOTE 047 - Internal Decision API: GET /portfolio/decision_state
    Returns portfolio-wide decision state summary. Read-only.
    """
    all_decisions = decision_api_get_all(snapshot_df, attrib_df, adaptive_state)
    total = len(all_decisions)

    status_dist = {}
    for d in all_decisions:
        s = d["status"].lower() if d["status"] else "unknown"
        status_dist[s] = status_dist.get(s, 0) + 1

    pending = status_dist.get("pending", 0)
    approved = status_dist.get("approved", 0)
    under_review = status_dist.get("under review", status_dist.get("review", 0))

    outcome_dist = {}
    for d in all_decisions:
        oc = d.get("decision_outcome")
        if oc:
            outcome_dist[str(oc)] = outcome_dist.get(str(oc), 0) + 1

    learning_state = {}
    if adaptive_state and isinstance(adaptive_state, dict):
        learning_state = {
            "learning_grade": adaptive_state.get("learning_grade", ""),
            "lessons_count": len(adaptive_state.get("lessons", [])),
            "friction_areas": len(adaptive_state.get("friction_areas", []))
        }

    return {
        "total_decisions": total,
        "pending": pending,
        "approved": approved,
        "under_review": under_review,
        "status_distribution": status_dist,
        "outcome_distribution": outcome_dist,
        "learning_state": learning_state
    }


def decision_api_ingest_external(decision_obj):
    """
    NOTE 047 - Internal Decision API: POST /decision (stub)
    Validates and appends an externally-sourced decision object.
    Phase 1 stub - structural placeholder for Phase 2 integration.
    Returns (success: bool, message: str).
    """
    required_fields = ["decision_id", "wave_name", "decision_type", "timestamp", "status"]
    if not decision_obj or not isinstance(decision_obj, dict):
        return False, "Invalid decision object"
    missing = [f for f in required_fields if not decision_obj.get(f)]
    if missing:
        return False, f"Missing required fields: {', '.join(missing)}"

    decision_obj["source"] = "External system"

    try:
        existing = []
        if os.path.exists("data/decision_log.json"):
            with open("data/decision_log.json", "r") as f:
                existing = json.load(f)

        raw_status = (decision_obj.get("status", "") or "").strip().lower()
        canonical_status = raw_status if raw_status in ("approved", "pending", "review", "rejected", "deferred") else "pending"
        mapped = {
            "id": decision_obj.get("decision_id", ""),
            "wave": decision_obj.get("wave_name", ""),
            "type": decision_obj.get("decision_type", ""),
            "timestamp": decision_obj.get("timestamp", ""),
            "status": canonical_status,
            "source": "External system",
            "action": decision_obj.get("signal_summary", ""),
            "rationale": decision_obj.get("signal_summary", ""),
            "regime_at_decision": decision_obj.get("regime_context", ""),
            "approved_by": decision_obj.get("actor", "")
        }
        existing.append(mapped)

        if not SANDBOX_MODE:
            with open("data/decision_log.json", "w") as f:
                json.dump(existing, f, indent=2)

        decision_event_log.append({
            "event_type": "decision_created",
            "decision_id": decision_obj.get("decision_id", ""),
            "timestamp": decision_obj.get("timestamp", datetime.now().isoformat()),
            "source": "external"
        })

        return True, "Decision ingested successfully"
    except Exception as e:
        return False, f"Ingestion failed: {str(e)}"


decision_event_log = []


def build_decision_memory_index(snapshot_df=None, attrib_df=None, adaptive_state=None):
    """
    NOTE 048 - Decision Memory Index Builder
    Constructs a structured memory index from existing decisions.
    All data from real system sources. Observational only, non-executing.
    """
    memory_index = []
    try:
        if os.path.exists("data/decision_log.json"):
            with open("data/decision_log.json", "r") as f:
                decisions = json.load(f)
        else:
            decisions = []
    except Exception:
        decisions = []

    for raw_dec in decisions:
        decision_id = raw_dec.get("id", "")
        decision_type = raw_dec.get("type", raw_dec.get("decision_type", ""))
        wave_name = raw_dec.get("wave", "")
        regime_context = raw_dec.get("regime_at_decision", "")
        status = (raw_dec.get("status", "") or "").strip().lower()

        primary_driver = ""
        confidence_level = "Moderate"
        outcome_alpha_30d = None
        outcome_alpha_90d = None
        outcome_alpha_365d = None
        outcome_alignment = "Insufficient History"

        if attrib_df is not None and not attrib_df.empty and wave_name and "wave" in attrib_df.columns:
            try:
                wave_attrib = attrib_df[attrib_df["wave"].str.lower() == wave_name.lower()]
                if wave_attrib.empty:
                    wn_tokens = [t.lower() for t in wave_name.split() if t.lower() not in ("wave", "the", "institutional")]
                    for token in wn_tokens[:2]:
                        wave_attrib = attrib_df[attrib_df["wave"].str.lower().str.contains(token, na=False)]
                        if not wave_attrib.empty:
                            break
                if not wave_attrib.empty:
                    h30 = wave_attrib[wave_attrib["horizon"] == 30] if "horizon" in wave_attrib.columns else wave_attrib
                    if not h30.empty:
                        row = h30.iloc[0]
                        components = {}
                        for comp_col in ["selection_alpha", "momentum_alpha", "volatility_alpha", "regime_alpha", "exposure_alpha"]:
                            if comp_col in row.index and pd.notna(row[comp_col]):
                                components[comp_col] = float(row[comp_col])
                        if components:
                            best_comp = max(components, key=lambda k: abs(components[k]))
                            primary_driver = best_comp.replace("_alpha", "").replace("_", " ").title()
            except Exception:
                pass

        if snapshot_df is not None and not snapshot_df.empty and wave_name:
            try:
                dn_col = "display_name" if "display_name" in snapshot_df.columns else "wave_name" if "wave_name" in snapshot_df.columns else None
                if dn_col:
                    wave_snap = snapshot_df[snapshot_df[dn_col].str.lower() == wave_name.lower()]
                    if wave_snap.empty:
                        wn_tokens = [t.lower() for t in wave_name.split() if t.lower() not in ("wave", "the", "institutional")]
                        for token in wn_tokens[:2]:
                            wave_snap = snapshot_df[snapshot_df[dn_col].str.lower().str.contains(token, na=False)]
                            if not wave_snap.empty:
                                break
                    if not wave_snap.empty:
                        row = wave_snap.iloc[0]
                        if "alpha_30d" in row.index and pd.notna(row["alpha_30d"]):
                            outcome_alpha_30d = float(row["alpha_30d"])
                        if "alpha_60d" in row.index and pd.notna(row["alpha_60d"]):
                            outcome_alpha_90d = float(row["alpha_60d"])
                        if "alpha_365d" in row.index and pd.notna(row["alpha_365d"]):
                            outcome_alpha_365d = float(row["alpha_365d"])
            except Exception:
                pass

        if adaptive_state and isinstance(adaptive_state, dict):
            lg = adaptive_state.get("learning_grade", "")
            if lg in ("A+", "A", "A-"):
                confidence_level = "High"
            elif lg in ("B+", "B", "B-"):
                confidence_level = "Moderate"
            elif lg:
                confidence_level = "Low"

        has_outcome = outcome_alpha_30d is not None or outcome_alpha_90d is not None or outcome_alpha_365d is not None
        if has_outcome:
            pos_count = 0
            neg_count = 0
            for ov in [outcome_alpha_30d, outcome_alpha_90d, outcome_alpha_365d]:
                if ov is not None:
                    if ov >= 0:
                        pos_count += 1
                    else:
                        neg_count += 1

            rationale_lower = (raw_dec.get("rationale", "") or "").lower()
            is_defensive = any(kw in rationale_lower for kw in ["defensive", "reduce", "risk-off", "de-risk"])

            if is_defensive:
                if neg_count == 0:
                    outcome_alignment = "Aligned"
                elif pos_count > neg_count:
                    outcome_alignment = "Aligned"
                elif pos_count == neg_count:
                    outcome_alignment = "Mixed"
                else:
                    outcome_alignment = "External"
            else:
                if pos_count > neg_count:
                    outcome_alignment = "Aligned"
                elif pos_count == neg_count:
                    outcome_alignment = "Mixed"
                else:
                    outcome_alignment = "External"
        else:
            outcome_alignment = "Insufficient History"

        memory_index.append({
            "decision_id": decision_id,
            "decision_type": decision_type,
            "wave_name": wave_name,
            "primary_driver": primary_driver,
            "regime_context": regime_context,
            "confidence_level": confidence_level,
            "status": status,
            "outcome_alignment": outcome_alignment,
            "outcome_alpha_30d": outcome_alpha_30d,
            "outcome_alpha_90d": outcome_alpha_90d,
            "outcome_alpha_365d": outcome_alpha_365d,
        })

    return memory_index


def compute_memory_patterns(memory_index):
    """
    NOTE 048 - Decision Memory Pattern Summary
    Groups decisions by type/driver and computes alignment statistics.
    Only includes decisions with real outcome data.
    Observational only, non-executing.
    """
    patterns = {}
    for entry in memory_index:
        if entry.get("outcome_alignment") == "Insufficient History":
            continue

        dec_type = entry.get("decision_type", "Unknown")
        driver = entry.get("primary_driver", "")
        group_key = dec_type
        if driver:
            group_key = f"{dec_type}|{driver}"

        if group_key not in patterns:
            patterns[group_key] = {
                "decision_type": dec_type,
                "primary_driver": driver,
                "decisions": [],
            }
        patterns[group_key]["decisions"].append(entry)

    result = {}
    for group_key, group_data in patterns.items():
        decisions = group_data["decisions"]
        total = len(decisions)

        if total < 3:
            result[group_key] = {
                "decision_type": group_data["decision_type"],
                "primary_driver": group_data["primary_driver"],
                "total_similar_decisions": total,
                "status": "Limited history",
            }
            continue

        aligned = sum(1 for d in decisions if d.get("outcome_alignment") == "Aligned")
        alignment_rate = aligned / total if total > 0 else 0

        a30_vals = [d["outcome_alpha_30d"] for d in decisions if d.get("outcome_alpha_30d") is not None]
        a90_vals = [d["outcome_alpha_90d"] for d in decisions if d.get("outcome_alpha_90d") is not None]
        a365_vals = [d["outcome_alpha_365d"] for d in decisions if d.get("outcome_alpha_365d") is not None]

        result[group_key] = {
            "decision_type": group_data["decision_type"],
            "primary_driver": group_data["primary_driver"],
            "total_similar_decisions": total,
            "alignment_rate": alignment_rate,
            "avg_alpha_30d": sum(a30_vals) / len(a30_vals) if a30_vals else None,
            "avg_alpha_90d": sum(a90_vals) / len(a90_vals) if a90_vals else None,
            "avg_alpha_365d": sum(a365_vals) / len(a365_vals) if a365_vals else None,
            "status": "Sufficient",
        }

    type_only = {}
    for entry in memory_index:
        if entry.get("outcome_alignment") == "Insufficient History":
            continue
        dec_type = entry.get("decision_type", "Unknown")
        if dec_type not in type_only:
            type_only[dec_type] = {"decisions": []}
        type_only[dec_type]["decisions"].append(entry)

    for dec_type, tdata in type_only.items():
        tkey = f"_type_{dec_type}"
        decisions = tdata["decisions"]
        total = len(decisions)
        if total < 3:
            result[tkey] = {
                "decision_type": dec_type,
                "primary_driver": "",
                "total_similar_decisions": total,
                "status": "Limited history",
            }
            continue
        aligned = sum(1 for d in decisions if d.get("outcome_alignment") == "Aligned")
        a30_vals = [d["outcome_alpha_30d"] for d in decisions if d.get("outcome_alpha_30d") is not None]
        a90_vals = [d["outcome_alpha_90d"] for d in decisions if d.get("outcome_alpha_90d") is not None]
        a365_vals = [d["outcome_alpha_365d"] for d in decisions if d.get("outcome_alpha_365d") is not None]
        result[tkey] = {
            "decision_type": dec_type,
            "primary_driver": "",
            "total_similar_decisions": total,
            "alignment_rate": aligned / total if total > 0 else 0,
            "avg_alpha_30d": sum(a30_vals) / len(a30_vals) if a30_vals else None,
            "avg_alpha_90d": sum(a90_vals) / len(a90_vals) if a90_vals else None,
            "avg_alpha_365d": sum(a365_vals) / len(a365_vals) if a365_vals else None,
            "status": "Sufficient",
        }

    return result


def render_decision_memory_context_html(decision_type, primary_driver, memory_patterns):
    """
    NOTE 048 - Renders Decision Memory Context block HTML for a decision card.
    Returns HTML string. Observational only.
    """
    pattern = None
    if primary_driver:
        key = f"{decision_type}|{primary_driver}"
        pattern = memory_patterns.get(key)
    if not pattern or pattern.get("status") == "Limited history":
        type_key = f"_type_{decision_type}"
        type_pattern = memory_patterns.get(type_key)
        if type_pattern and type_pattern.get("status") == "Sufficient":
            pattern = type_pattern
        elif not pattern:
            pattern = type_pattern

    html = '<div style="margin-top: 10px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,0.06);">'
    html += '<span style="color: #9EA3AE; font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; font-weight: 600;">Decision Memory Context</span>'

    if not pattern:
        html += '<div style="color: #6B7280; font-size: 11px; margin-top: 6px; font-style: italic;">Decision memory context unavailable due to insufficient outcome history.</div>'
    elif pattern.get("status") == "Limited history":
        html += '<div style="color: #6B7280; font-size: 11px; margin-top: 6px; font-style: italic;">Limited historical decision memory available for this decision type.</div>'
    else:
        count = pattern.get("total_similar_decisions", 0)
        alignment_pct = pattern.get("alignment_rate", 0) * 100
        a90 = pattern.get("avg_alpha_90d")
        a365 = pattern.get("avg_alpha_365d")

        a90_str = f"{a90*100:+.2f}%" if a90 is not None else "-"
        a365_str = f"{a365*100:+.2f}%" if a365 is not None else "-"

        align_color = "#48BB78" if alignment_pct >= 60 else "#ECC94B" if alignment_pct >= 40 else "#EF4444"
        a90_color = "#48BB78" if a90 is not None and a90 >= 0 else "#EF4444" if a90 is not None else "#6B7280"
        a365_color = "#48BB78" if a365 is not None and a365 >= 0 else "#EF4444" if a365 is not None else "#6B7280"

        html += f'''<div style="display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; gap: 8px; margin-top: 6px;">
<div><span style="color: #6B7280; font-size: 10px;">Similar Decisions</span><br><span style="color: #C8CCD4; font-size: 12px; font-weight: 600;">{count}</span></div>
<div><span style="color: #6B7280; font-size: 10px;">Alignment Rate</span><br><span style="color: {align_color}; font-size: 12px; font-weight: 600;">{alignment_pct:.0f}%</span></div>
<div><span style="color: #6B7280; font-size: 10px;">Avg 90D Alpha</span><br><span style="color: {a90_color}; font-size: 12px; font-weight: 600; font-family: \'SF Mono\', monospace;">{a90_str}</span></div>
<div><span style="color: #6B7280; font-size: 10px;">Avg 365D Alpha</span><br><span style="color: {a365_color}; font-size: 12px; font-weight: 600; font-family: \'SF Mono\', monospace;">{a365_str}</span></div>
</div>'''

    html += '<div style="margin-top: 8px;"><span style="color: #555A65; font-size: 9px; font-style: italic;">Memory context is observational and derived from prior decisions under similar conditions.</span></div>'
    html += '</div>'
    return html


def compute_review_explanation(wave_name, attribution_df, snapshot_df):
    """
    NOTE 049 - Review Driver Explanation for wave-level review cards.
    Returns (primary_detractor, review_focus) from real attribution data.
    Observational only, non-executing.
    """
    try:
        if attribution_df is None or attribution_df.empty:
            return None, None

        wcol = "wave" if "wave" in attribution_df.columns else "wave_name" if "wave_name" in attribution_df.columns else None
        if not wcol:
            return None, None

        wave_attr = attribution_df[attribution_df[wcol].str.lower() == wave_name.lower()]
        if wave_attr.empty:
            wn_tokens = [t.lower() for t in wave_name.split() if t.lower() not in ("wave", "the", "institutional")]
            for token in wn_tokens[:2]:
                wave_attr = attribution_df[attribution_df[wcol].str.lower().str.contains(token, na=False)]
                if not wave_attr.empty:
                    break

        if wave_attr.empty:
            return None, None

        row = wave_attr[wave_attr["horizon"] == 30] if "horizon" in wave_attr.columns else wave_attr
        if row.empty:
            return None, None

        row = row.iloc[0]

        driver_values = {}
        driver_col_map = {
            "Selection": "selection_alpha",
            "Momentum": "momentum_alpha",
            "Volatility": "volatility_alpha",
            "Regime": "regime_alpha",
            "Exposure": "exposure_alpha",
        }
        for label, col in driver_col_map.items():
            if col in row.index and pd.notna(row[col]):
                driver_values[label] = float(row[col])

        if not driver_values:
            return None, None

        primary_detractor = min(driver_values, key=driver_values.get)
        worst_value = driver_values[primary_detractor]

        if worst_value >= 0:
            return None, None

        review_map = {
            "Selection": "Security-level detractors or sector drift.",
            "Momentum": "Cross-horizon signal instability.",
            "Volatility": "Overlay or regime volatility drag.",
            "Regime": "Positioning misaligned with regime conditions.",
            "Exposure": "Allocation drift vs target exposure.",
        }

        review_focus = review_map.get(primary_detractor, None)

        return primary_detractor, review_focus

    except Exception:
        return None, None


@st.cache_data(ttl=90, show_spinner=False)
def _fetch_global_futures_data():
    """
    NOTE 046 + Finnhub upgrade - Fetch Global Futures/Market Context data.
    Primary: Finnhub API (real-time quotes via ETF proxies).
    Fallback: yfinance (delayed quotes) if Finnhub unavailable.
    Returns list of dicts with asset, last, change, direction, source.
    """
    import os

    symbols = [
        ("S&P 500 Futures", "SPY", "ES=F"),
        ("Nasdaq 100 Futures", "QQQ", "NQ=F"),
        ("10Y Treasury Futures", "TLT", "ZN=F"),
        ("Crude Oil", "USO", "CL=F"),
        ("Gold", "GLD", "GC=F"),
        ("U.S. Dollar Index", "UUP", "DX=F"),
    ]

    results = []
    finnhub_key = os.environ.get("FINNHUB_API_KEY", "")
    finnhub_client = None

    if finnhub_key:
        try:
            import finnhub
            finnhub_client = finnhub.Client(api_key=finnhub_key)
        except Exception:
            finnhub_client = None

    for label, finnhub_sym, yf_fallback_sym in symbols:
        last_price = None
        pct_change = None
        source = None

        if finnhub_client:
            try:
                q = finnhub_client.quote(finnhub_sym)
                if q and q.get("c") and q["c"] > 0:
                    last_price = float(q["c"])
                    pct_change = float(q.get("dp", 0) or 0)
                    source = "finnhub"
            except Exception:
                pass

        if last_price is None:
            try:
                import yfinance as yf
                for sym in [yf_fallback_sym, finnhub_sym]:
                    try:
                        ticker = yf.Ticker(sym)
                        hist = ticker.history(period="2d")
                        if hist is not None and len(hist) >= 2:
                            prev_close = float(hist["Close"].iloc[-2])
                            curr_close = float(hist["Close"].iloc[-1])
                            if prev_close > 0:
                                last_price = curr_close
                                pct_change = ((curr_close - prev_close) / prev_close) * 100
                                source = "yfinance"
                                break
                        elif hist is not None and len(hist) == 1:
                            last_price = float(hist["Close"].iloc[-1])
                            pct_change = 0.0
                            source = "yfinance"
                            break
                    except Exception:
                        continue
            except Exception:
                pass

        if last_price is not None and pct_change is not None:
            if pct_change > 0.30:
                direction = "Strength"
            elif pct_change < -0.30:
                direction = "Weakness"
            else:
                direction = "Stable"

            results.append({
                "asset": label,
                "last": last_price,
                "change": pct_change,
                "direction": direction,
                "source": source or "unknown",
            })

    return results


def render_global_futures_context(compact=False):
    """
    NOTE 046 - Global Futures Context Layer (24-Hour Market Orientation)
    Renders institutional futures context table with overnight summary.
    Observational only, non-executing.
    """
    futures_data = _fetch_global_futures_data()

    if not futures_data:
        return

    section_label = "GLOBAL FUTURES CONTEXT" if not compact else "FUTURES CONTEXT"
    st.markdown(f"""<div style="margin: {'8px 0 4px 0' if compact else '16px 0 8px 0'};">
<span style="color: #3A6FF7; font-size: 11px; font-weight: 600; letter-spacing: 0.04em;">{section_label}</span>
</div>""", unsafe_allow_html=True)

    dir_colors = {
        "Strength": "#48BB78",
        "Weakness": "#EF4444",
        "Stable": "#9EA3AE",
    }

    table_html = '<div style="background: #151A22; border: 1px solid #2A2F3A; padding: 14px 16px; border-radius: 6px; margin-bottom: 8px;">'
    table_html += '<table style="width: 100%; border-collapse: collapse;">'
    table_html += '<tr style="border-bottom: 1px solid rgba(255,255,255,0.06);">'
    table_html += '<th style="color: #6B7280; font-size: 10px; text-align: left; padding: 4px 0; font-weight: 500;">Asset</th>'
    table_html += '<th style="color: #6B7280; font-size: 10px; text-align: right; padding: 4px 0; font-weight: 500;">Last</th>'
    table_html += '<th style="color: #6B7280; font-size: 10px; text-align: right; padding: 4px 0; font-weight: 500;">Change</th>'
    table_html += '<th style="color: #6B7280; font-size: 10px; text-align: right; padding: 4px 0; font-weight: 500;">Direction</th>'
    table_html += '</tr>'

    for fd in futures_data:
        chg_color = "#48BB78" if fd["change"] >= 0 else "#EF4444"
        dir_color = dir_colors.get(fd["direction"], "#9EA3AE")

        if fd["last"] >= 1000:
            last_fmt = f"{fd['last']:,.0f}"
        elif fd["last"] >= 100:
            last_fmt = f"{fd['last']:,.1f}"
        else:
            last_fmt = f"{fd['last']:,.2f}"

        table_html += f'<tr style="border-bottom: 1px solid rgba(255,255,255,0.03);">'
        table_html += f'<td style="color: #C8CCD4; font-size: 11px; padding: 5px 0;">{fd["asset"]}</td>'
        table_html += f'<td style="color: #C8CCD4; font-size: 11px; text-align: right; padding: 5px 0; font-family: \'SF Mono\', monospace;">{last_fmt}</td>'
        table_html += f'<td style="color: {chg_color}; font-size: 11px; text-align: right; padding: 5px 0; font-family: \'SF Mono\', monospace;">{fd["change"]:+.2f}%</td>'
        table_html += f'<td style="color: {dir_color}; font-size: 11px; text-align: right; padding: 5px 0; font-weight: 600;">{fd["direction"]}</td>'
        table_html += '</tr>'

    table_html += '</table>'

    eq_names = {"S&P 500 Futures", "Nasdaq 100 Futures"}
    def_names = {"Gold", "10Y Treasury Futures"}
    cyc_names = {"Crude Oil"}

    eq_dirs = [fd["direction"] for fd in futures_data if fd["asset"] in eq_names]
    def_dirs = [fd["direction"] for fd in futures_data if fd["asset"] in def_names]
    cyc_dirs = [fd["direction"] for fd in futures_data if fd["asset"] in cyc_names]

    eq_weak = all(d == "Weakness" for d in eq_dirs) if eq_dirs else False
    eq_strong = all(d == "Strength" for d in eq_dirs) if eq_dirs else False
    def_strong = any(d == "Strength" for d in def_dirs) if def_dirs else False
    cyc_strong = any(d == "Strength" for d in cyc_dirs) if cyc_dirs else False

    if eq_weak and def_strong:
        summary = "Futures indicate a mild risk-off tone across major asset classes."
    elif eq_strong and cyc_strong:
        summary = "Futures indicate a constructive risk-on tone across major asset classes."
    else:
        summary = "Futures conditions appear mixed across major asset classes."

    table_html += f'<div style="margin-top: 10px; padding-top: 8px; border-top: 1px solid rgba(255,255,255,0.04);">'
    table_html += f'<span style="color: #9EA3AE; font-size: 11px; font-style: italic;">{summary}</span>'
    table_html += '</div>'
    table_html += '</div>'

    st.markdown(table_html, unsafe_allow_html=True)

    sources = set(fd.get("source", "unknown") for fd in futures_data)
    source_label = "Finnhub (real-time)" if "finnhub" in sources else "yfinance (delayed)"
    from datetime import datetime
    import pytz
    _now_et = datetime.now(pytz.timezone("US/Eastern")).strftime("%I:%M %p ET")

    st.markdown(f"""<div style="color: #555A65; font-size: 9px; text-align: center; margin: 4px 0 10px 0; font-style: italic;">
Futures context is observational and provided for market orientation only. No execution guidance is provided.<br/>
Data via {source_label} &middot; Last refresh: {_now_et}
</div>""", unsafe_allow_html=True)


