def load_market_cache():
    """Load cached market data from persistent storage."""
    try:
        if os.path.exists(MARKET_CACHE_PATH):
            with open(MARKET_CACHE_PATH, 'r') as f:
                cache = json.load(f)
            cache_date = datetime.strptime(cache.get("timestamp", "2020-01-01"), "%Y-%m-%d")
            age_days = (datetime.now() - cache_date).days
            if age_days <= MARKET_CACHE_MAX_AGE_DAYS:
                cache["age_days"] = age_days
                cache["is_stale"] = False
                print(f"[MI] load_market_cache: cache hit, age={age_days} days, provider={cache.get('source_provider')}")
                return cache
            else:
                cache["age_days"] = age_days
                cache["is_stale"] = True
                print(f"[MI] load_market_cache: cache stale (age={age_days} days > {MARKET_CACHE_MAX_AGE_DAYS}), returning stale")
                return cache
        print(f"[MI] load_market_cache: cache file not found at {MARKET_CACHE_PATH}")
        return None
    except Exception as exc:
        print(f"[MI] load_market_cache: error reading cache: {exc}")
        return None



def save_market_cache(spy_return_30d, spy_return_60d, spy_return_365d, 
                      qqq_return_30d, qqq_return_60d, qqq_return_365d,
                      vix_level, vix_roc, provider_name="Unknown"):
    """Persist market data to cache for fallback use."""
    try:
        cache_data = {
            "timestamp": datetime.now().strftime("%Y-%m-%d"),
            "spy_return_30d": spy_return_30d,
            "spy_return_60d": spy_return_60d,
            "spy_return_365d": spy_return_365d,
            "qqq_return_30d": qqq_return_30d,
            "qqq_return_60d": qqq_return_60d,
            "qqq_return_365d": qqq_return_365d,
            "vix_level": vix_level,
            "vix_roc": vix_roc,
            "source_provider": provider_name
        }
        os.makedirs(os.path.dirname(MARKET_CACHE_PATH), exist_ok=True)
        with open(MARKET_CACHE_PATH, 'w') as f:
            json.dump(cache_data, f, indent=2)
        return True
    except Exception:
        return False



def log_provider_failure(provider_name, reason):
    """Log provider failures for debugging (not exposed in UI)."""
    try:
        log_entry = {
            "timestamp": datetime.now().isoformat(),
            "provider": provider_name,
            "reason": reason[:200]
        }
        os.makedirs(os.path.dirname(PROVIDER_LOG_PATH), exist_ok=True)
        logs = []
        if os.path.exists(PROVIDER_LOG_PATH):
            with open(PROVIDER_LOG_PATH, 'r') as f:
                logs = json.load(f)
        logs.append(log_entry)
        logs = logs[-50:]
        if not SANDBOX_MODE:
            with open(PROVIDER_LOG_PATH, 'w') as f:
                json.dump(logs, f, indent=2)
    except Exception:
        pass

# -----------------------------------------------
# MARKET DATA PROVIDER ABSTRACTION LAYER
# Priority: Polygon.io → Alpha Vantage → yfinance → Cache → Baseline
# -----------------------------------------------



def fetch_polygon_data(ticker, lookback_days):
    """
    PRIMARY PROVIDER: Polygon.io
    Returns dict with 'close_prices' series, 'success', 'error'.
    """
    try:
        api_key = os.environ.get("POLYGON_API_KEY", "")
        if not api_key:
            return {"success": False, "error": "API key not configured", "close_prices": pd.Series()}
        
        import requests
        end_date = datetime.now()
        start_date = end_date - timedelta(days=lookback_days + 30)
        
        vix_ticker = "I:VIX" if ticker == "^VIX" else ticker
        
        url = f"https://api.polygon.io/v2/aggs/ticker/{vix_ticker}/range/1/day/{start_date.strftime('%Y-%m-%d')}/{end_date.strftime('%Y-%m-%d')}"
        params = {"adjusted": "true", "sort": "asc", "apiKey": api_key}
        
        response = requests.get(url, params=params, timeout=10)
        
        if response.status_code == 429:
            return {"success": False, "error": "Rate limit exceeded", "close_prices": pd.Series()}
        elif response.status_code == 403:
            return {"success": False, "error": "API key invalid or expired", "close_prices": pd.Series()}
        elif response.status_code != 200:
            return {"success": False, "error": f"HTTP {response.status_code}", "close_prices": pd.Series()}
        
        data = response.json()
        if data.get("resultsCount", 0) == 0:
            return {"success": False, "error": "No data returned", "close_prices": pd.Series()}
        
        results = data.get("results", [])
        dates = [datetime.fromtimestamp(r["t"] / 1000) for r in results]
        closes = [r["c"] for r in results]
        
        return {"success": True, "error": None, "close_prices": pd.Series(closes, index=dates)}
    
    except Exception as e:
        error_type = type(e).__name__
        if "Timeout" in error_type:
            return {"success": False, "error": "Request timeout", "close_prices": pd.Series()}
        elif "ConnectionError" in error_type:
            return {"success": False, "error": "Network connection error", "close_prices": pd.Series()}
        return {"success": False, "error": str(e)[:100], "close_prices": pd.Series()}



def fetch_alphavantage_data(ticker, lookback_days):
    """
    SECONDARY PROVIDER: Alpha Vantage
    Returns dict with 'close_prices' series, 'success', 'error'.
    """
    try:
        api_key = os.environ.get("ALPHAVANTAGE_API_KEY", "")
        if not api_key:
            return {"success": False, "error": "API key not configured", "close_prices": pd.Series()}
        
        import requests
        
        if ticker == "^VIX":
            return {"success": False, "error": "VIX not supported by Alpha Vantage free tier", "close_prices": pd.Series()}
        
        url = "https://www.alphavantage.co/query"
        params = {
            "function": "TIME_SERIES_DAILY_ADJUSTED",
            "symbol": ticker,
            "outputsize": "full" if lookback_days > 100 else "compact",
            "apikey": api_key
        }
        
        response = requests.get(url, params=params, timeout=15)
        
        if response.status_code != 200:
            return {"success": False, "error": f"HTTP {response.status_code}", "close_prices": pd.Series()}
        
        data = response.json()
        
        if "Note" in data:
            return {"success": False, "error": "Rate limit exceeded", "close_prices": pd.Series()}
        if "Error Message" in data:
            return {"success": False, "error": "Invalid ticker or API error", "close_prices": pd.Series()}
        
        time_series = data.get("Time Series (Daily)", {})
        if not time_series:
            return {"success": False, "error": "No data returned", "close_prices": pd.Series()}
        
        dates = [datetime.strptime(d, "%Y-%m-%d") for d in time_series.keys()]
        closes = [float(time_series[d]["5. adjusted close"]) for d in time_series.keys()]
        
        series = pd.Series(closes, index=dates).sort_index()
        return {"success": True, "error": None, "close_prices": series}
    
    except Exception as e:
        error_type = type(e).__name__
        if "Timeout" in error_type:
            return {"success": False, "error": "Request timeout", "close_prices": pd.Series()}
        elif "ConnectionError" in error_type:
            return {"success": False, "error": "Network connection error", "close_prices": pd.Series()}
        return {"success": False, "error": str(e)[:100], "close_prices": pd.Series()}



def fetch_yfinance_data(ticker, start_date_str, end_date_str):
    """
    TERTIARY PROVIDER: yfinance (original fallback)
    Returns dict with 'close_prices' series, 'success', 'error'.
    """
    try:
        data = yf.download(ticker, start=start_date_str, end=end_date_str, progress=False)
        if len(data) > 0:
            close_raw = data["Close"]
            if hasattr(close_raw, 'squeeze'):
                close_series = close_raw.squeeze().dropna()
            else:
                close_series = close_raw.dropna()
            return {"success": True, "error": None, "close_prices": close_series}
        return {"success": False, "error": "No data returned", "close_prices": pd.Series()}
    except Exception as e:
        return {"success": False, "error": str(e)[:100], "close_prices": pd.Series()}



def fetch_market_data_with_providers(ticker, lookback_days):
    """
    UNIFIED MARKET DATA FETCHER WITH PROVIDER FALLBACK
    Priority: Polygon.io → Alpha Vantage → yfinance
    Returns: dict with 'close_prices', 'provider', 'success', 'errors'
    """
    errors = {}
    
    polygon_result = fetch_polygon_data(ticker, lookback_days)
    if polygon_result["success"] and len(polygon_result["close_prices"]) >= 20:
        return {
            "close_prices": polygon_result["close_prices"],
            "provider": "Polygon",
            "success": True,
            "errors": errors
        }
    else:
        errors["Polygon"] = polygon_result.get("error", "Unknown error")
        log_provider_failure("Polygon", errors["Polygon"])
    
    alpha_result = fetch_alphavantage_data(ticker, lookback_days)
    if alpha_result["success"] and len(alpha_result["close_prices"]) >= 20:
        return {
            "close_prices": alpha_result["close_prices"],
            "provider": "Alpha Vantage",
            "success": True,
            "errors": errors
        }
    else:
        errors["Alpha Vantage"] = alpha_result.get("error", "Unknown error")
        log_provider_failure("Alpha Vantage", errors["Alpha Vantage"])
    
    end_date = datetime.now()
    start_date = end_date - timedelta(days=lookback_days + 30)
    yf_result = fetch_yfinance_data(ticker, start_date.strftime("%Y-%m-%d"), end_date.strftime("%Y-%m-%d"))
    if yf_result["success"] and len(yf_result["close_prices"]) >= 20:
        return {
            "close_prices": yf_result["close_prices"],
            "provider": "yfinance",
            "success": True,
            "errors": errors
        }
    else:
        errors["yfinance"] = yf_result.get("error", "Unknown error")
        log_provider_failure("yfinance", errors["yfinance"])
    
    return {
        "close_prices": pd.Series(),
        "provider": None,
        "success": False,
        "errors": errors
    }



def fetch_market_data(ticker, start_date_str, end_date_str):
    """Legacy wrapper for backward compatibility."""
    try:
        data = yf.download(ticker, start=start_date_str, end=end_date_str, progress=False)
        if len(data) > 0:
            close_raw = data["Close"]
            if hasattr(close_raw, 'squeeze'):
                return close_raw.squeeze().dropna()
            return close_raw.dropna()
        return pd.Series()
    except Exception as e:
        return pd.Series()

# -----------------------------------------------
# INTRADAY CONFIDENCE MODULATION (CRITICAL: Affects confidence ONLY, never direction score)
# -----------------------------------------------



def compute_direction_assessment(snapshot_df, attrib_df, horizon_key):
    """
    Compute direction score and evidence for a single horizon.
    Score bounded to [-1.00, +1.00].
    All signals derived from existing data sources only.
    """
    assessment = {
        "direction_score": 0.0,
        "direction_label": "Neutral / Transitional",
        "confidence": "Moderate",
        "evidence": {
            "structural": [],
            "risk_volatility": [],
            "system_alignment": [],
            "conflicts": []
        }
    }
    
    if snapshot_df is None or snapshot_df.empty:
        return assessment
    
    horizon_map = {
        "short": {"alpha_col": "alpha_30d", "return_col": "return_30d", "days": 30},
        "intermediate": {"alpha_col": "alpha_60d", "return_col": "return_60d", "days": 60},
        "long": {"alpha_col": "alpha_365d", "return_col": "return_365d", "days": 365}
    }
    
    config = horizon_map.get(horizon_key, horizon_map["long"])
    alpha_col = config["alpha_col"]
    return_col = config["return_col"]
    horizon_days = config["days"]
    
    # Filter attribution data by horizon
    horizon_attrib = None
    if attrib_df is not None and len(attrib_df) > 0:
        if "horizon" in attrib_df.columns:
            horizon_attrib = attrib_df[attrib_df["horizon"] == horizon_days]
            if len(horizon_attrib) == 0:
                horizon_attrib = attrib_df
        else:
            horizon_attrib = attrib_df
    
    pillar_scores = []
    
    # ---- PILLAR 1: Structural Signals ----
    structural_score = 0.0
    if alpha_col in snapshot_df.columns:
        avg_alpha = snapshot_df[alpha_col].dropna().mean()
        if pd.notna(avg_alpha):
            structural_score = max(min(avg_alpha * 10, 1.0), -1.0)
            if avg_alpha > 0.01:
                assessment["evidence"]["structural"].append(f"Alpha Signal: +{avg_alpha*100:.2f}% (Positive)")
            elif avg_alpha < -0.01:
                assessment["evidence"]["structural"].append(f"Alpha Signal: {avg_alpha*100:.2f}% (Negative)")
            else:
                assessment["evidence"]["structural"].append(f"Alpha Signal: {avg_alpha*100:.2f}% (Neutral)")
    
    if return_col in snapshot_df.columns:
        avg_return = snapshot_df[return_col].dropna().mean()
        if pd.notna(avg_return):
            return_signal = max(min(avg_return * 5, 1.0), -1.0)
            structural_score = (structural_score + return_signal) / 2
            if avg_return > 0.03:
                assessment["evidence"]["structural"].append(f"Return Signal: +{avg_return*100:.2f}% (Strong)")
            elif avg_return < -0.02:
                assessment["evidence"]["structural"].append(f"Return Signal: {avg_return*100:.2f}% (Weak)")
    
    pillar_scores.append(("structural", structural_score))
    
    # ---- PILLAR 2: Risk & Volatility Context ----
    risk_score = 0.0
    if horizon_attrib is not None and "volatility_alpha" in horizon_attrib.columns:
        vol_alpha = horizon_attrib["volatility_alpha"].mean()
        vol_std = horizon_attrib["volatility_alpha"].std() if len(horizon_attrib) > 1 else 0
        if pd.notna(vol_alpha):
            risk_score = max(min(vol_alpha * 20, 1.0), -1.0)
            if vol_alpha < -0.005:
                assessment["evidence"]["risk_volatility"].append(f"Volatility Alpha: {vol_alpha*100:.2f}% (Drag)")
            elif vol_std > 0.015:
                assessment["evidence"]["risk_volatility"].append(f"Volatility Dispersion: {vol_std*100:.2f}% std (Elevated)")
            else:
                assessment["evidence"]["risk_volatility"].append(f"Volatility Alpha: {vol_alpha*100:.2f}% (Stable)")
    
    if horizon_attrib is not None and "regime_alpha" in horizon_attrib.columns:
        regime_alpha = horizon_attrib["regime_alpha"].mean()
        if pd.notna(regime_alpha):
            regime_signal = max(min(regime_alpha * 20, 1.0), -1.0)
            risk_score = (risk_score + regime_signal) / 2
            if regime_alpha > 0.005:
                assessment["evidence"]["risk_volatility"].append(f"Regime Alpha: +{regime_alpha*100:.2f}% (Positive)")
            elif regime_alpha < -0.005:
                assessment["evidence"]["risk_volatility"].append(f"Regime Alpha: {regime_alpha*100:.2f}% (Negative)")
    
    pillar_scores.append(("risk", risk_score))
    
    # ---- PILLAR 3: System Alignment ----
    alignment_score = 0.0
    if horizon_attrib is not None:
        component_vals = []
        for key in ["selection_alpha", "momentum_alpha", "volatility_alpha", "regime_alpha", "exposure_alpha"]:
            val = horizon_attrib[key].mean() if key in horizon_attrib.columns else None
            if val is not None and pd.notna(val):
                component_vals.append(val)
        
        if len(component_vals) >= 3:
            positive_count = sum(1 for v in component_vals if v > 0)
            alignment_ratio = positive_count / len(component_vals)
            alignment_score = (alignment_ratio - 0.5) * 2
            assessment["evidence"]["system_alignment"].append(f"Component Alignment: {positive_count}/{len(component_vals)} positive")
    
    if alpha_col in snapshot_df.columns:
        alpha_values = snapshot_df[alpha_col].dropna()
        if len(alpha_values) > 0:
            positive_waves = (alpha_values > 0).sum()
            total_waves = len(alpha_values)
            breadth_ratio = positive_waves / total_waves
            breadth_signal = (breadth_ratio - 0.5) * 2
            alignment_score = (alignment_score + breadth_signal) / 2
            assessment["evidence"]["system_alignment"].append(f"{positive_waves}/{total_waves} waves ({breadth_ratio*100:.0f}%) showed positive alpha")
    
    pillar_scores.append(("alignment", alignment_score))
    
    # ---- PILLAR 4: Trend/Momentum Context ----
    momentum_score = 0.0
    if horizon_attrib is not None and "momentum_alpha" in horizon_attrib.columns:
        mom_alpha = horizon_attrib["momentum_alpha"].mean()
        if pd.notna(mom_alpha):
            momentum_score = max(min(mom_alpha * 30, 1.0), -1.0)
    
    pillar_scores.append(("momentum", momentum_score))
    
    # ---- COMPOSITE DIRECTION SCORE ----
    if pillar_scores:
        weights = {"structural": 0.35, "risk": 0.25, "alignment": 0.25, "momentum": 0.15}
        weighted_sum = sum(weights.get(p[0], 0.25) * p[1] for p in pillar_scores)
        assessment["direction_score"] = max(min(weighted_sum, 1.0), -1.0)
    
    # ---- MAP SCORE TO LABEL ----
    score = assessment["direction_score"]
    if score >= 0.40:
        assessment["direction_label"] = "Bullish"
    elif score <= -0.40:
        assessment["direction_label"] = "Bearish / Defensive"
    else:
        assessment["direction_label"] = "Neutral / Transitional"
    
    # ---- DERIVE CONFIDENCE ----
    score_signs = [1 if p[1] > 0.1 else (-1 if p[1] < -0.1 else 0) for p in pillar_scores]
    agreement = abs(sum(score_signs)) / len(score_signs) if score_signs else 0
    
    if agreement >= 0.75:
        assessment["confidence"] = "High"
    elif agreement >= 0.4:
        assessment["confidence"] = "Moderate"
    else:
        assessment["confidence"] = "Low"
        if len([s for s in score_signs if s > 0]) > 0 and len([s for s in score_signs if s < 0]) > 0:
            assessment["evidence"]["conflicts"].append("Internal signals showed mixed directions")
    
    return assessment

# -----------------------------------------------
# MARKET CONTEXT CACHE MANAGEMENT (TIER 3 FALLBACK)
# -----------------------------------------------


def compute_market_context_assessment(horizon_key):
    """
    Compute direction score for Market Context using ONLY external market data.
    4-tier priority: 1) Polygon.io, 2) Alpha Vantage, 3) yfinance, 4) Cache, 5) Baseline.
    Score bounded to [-1.00, +1.00]. MUST emit non-zero directional bias.
    """
    assessment = {
        "direction_score": 0.0,
        "direction_label": "Neutral / Transitional",
        "confidence": "Moderate",
        "evidence": {
            "structural": [],
            "risk_volatility": [],
            "system_alignment": [],
            "conflicts": []
        },
        "data_available": False,
        "data_source": "Unknown",
        "data_provider": None,
        "data_timestamp": None,
        "debug_pillars": {}
    }
    
    horizon_map = {
        "short": {"days": 30, "label": "30D", "sensitivity": 1.0, "vix_weight": 0.35, "trend_weight": 0.35, "breadth_weight": 0.15, "vix_roc_weight": 0.15},
        "intermediate": {"days": 60, "label": "60D", "sensitivity": 0.7, "vix_weight": 0.25, "trend_weight": 0.40, "breadth_weight": 0.25, "vix_roc_weight": 0.10},
        "long": {"days": 365, "label": "365D", "sensitivity": 0.35, "vix_weight": 0.20, "trend_weight": 0.45, "breadth_weight": 0.30, "vix_roc_weight": 0.05}
    }
    
    config = horizon_map.get(horizon_key, horizon_map["long"])
    lookback_days = config["days"]
    sensitivity = config["sensitivity"]
    
    pillar_scores = []
    pillar_conflicts = 0
    debug_info = {"horizon": horizon_key, "sensitivity": sensitivity, "pillars": {}, "data_source": "Unknown", "provider_errors": {}}
    
    live_data_success = False
    spy_return = qqq_return = vix_level = vix_roc = None
    active_provider = None
    
    # ========== TIER 1-3: LIVE DATA PROVIDERS (Polygon → Alpha Vantage → yfinance) ==========
    try:
        spy_result = fetch_market_data_with_providers("SPY", max(lookback_days, 400))
        vix_result = fetch_market_data_with_providers("^VIX", max(lookback_days, 400))
        qqq_result = fetch_market_data_with_providers("QQQ", max(lookback_days, 400))
        
        spy_close = spy_result["close_prices"]
        vix_close = vix_result["close_prices"]
        qqq_close = qqq_result["close_prices"]
        
        for ticker, result in [("SPY", spy_result), ("VIX", vix_result), ("QQQ", qqq_result)]:
            if result.get("errors"):
                debug_info["provider_errors"][ticker] = result["errors"]
        
        debug_info["data_lengths"] = {"SPY": len(spy_close), "VIX": len(vix_close), "QQQ": len(qqq_close)}
        debug_info["providers_used"] = {"SPY": spy_result.get("provider"), "VIX": vix_result.get("provider"), "QQQ": qqq_result.get("provider")}
        
        if len(spy_close) >= 20 and len(vix_close) > 0:
            live_data_success = True
            active_provider = spy_result.get("provider", "Unknown")
            assessment["data_source"] = f"Live Market Data ({active_provider})"
            assessment["data_provider"] = active_provider
            assessment["data_timestamp"] = datetime.now().strftime("%Y-%m-%d %H:%M")
            debug_info["data_source"] = f"Live ({active_provider})"
            
            lookback_idx = min(lookback_days, len(spy_close) - 1)
            start_val = float(spy_close.iloc[-lookback_idx]) if lookback_idx < len(spy_close) else float(spy_close.iloc[0])
            end_val = float(spy_close.iloc[-1])
            spy_return = (end_val - start_val) / start_val if start_val != 0 else 0
            
            if len(qqq_close) >= 20:
                qqq_lookback = min(lookback_days, len(qqq_close) - 1)
                qqq_start = float(qqq_close.iloc[-qqq_lookback]) if qqq_lookback < len(qqq_close) else float(qqq_close.iloc[0])
                qqq_end = float(qqq_close.iloc[-1])
                qqq_return = (qqq_end - qqq_start) / qqq_start if qqq_start != 0 else 0
            else:
                qqq_return = spy_return
            
            vix_level = float(vix_close.iloc[-1])
            if len(vix_close) >= 10:
                vix_5d_ago = float(vix_close.iloc[-min(5, len(vix_close)-1)])
                vix_roc = (vix_level - vix_5d_ago) / vix_5d_ago if vix_5d_ago != 0 else 0
            else:
                vix_roc = 0
            
            spy_return_30d = spy_return if lookback_days == 30 else spy_return * (30 / lookback_days)
            spy_return_60d = spy_return if lookback_days == 60 else spy_return * (60 / lookback_days)
            spy_return_365d = spy_return if lookback_days == 365 else spy_return * (365 / lookback_days)
            qqq_return_30d = qqq_return if lookback_days == 30 else qqq_return * (30 / lookback_days)
            qqq_return_60d = qqq_return if lookback_days == 60 else qqq_return * (60 / lookback_days)
            qqq_return_365d = qqq_return if lookback_days == 365 else qqq_return * (365 / lookback_days)
            
            if not SANDBOX_MODE:
                save_market_cache(spy_return_30d, spy_return_60d, spy_return_365d,
                                  qqq_return_30d, qqq_return_60d, qqq_return_365d,
                                  vix_level, vix_roc, provider_name=active_provider)
    
    except Exception as e:
        debug_info["live_error"] = str(e)[:100]
    
    # ========== TIER 4: CACHED DATA FALLBACK ==========
    if not live_data_success:
        cached_data = load_market_cache()
        if cached_data and not cached_data.get("is_stale", True):
            assessment["data_source"] = "Cached Market Data"
            assessment["data_provider"] = cached_data.get("source_provider", "Unknown")
            assessment["data_timestamp"] = cached_data.get("timestamp", "Unknown")
            debug_info["data_source"] = f"Cached ({cached_data.get('age_days', '?')} days old)"
            
            horizon_return_key = {"short": "30d", "intermediate": "60d", "long": "365d"}.get(horizon_key, "30d")
            spy_return = cached_data.get(f"spy_return_{horizon_return_key}", 0.02)
            qqq_return = cached_data.get(f"qqq_return_{horizon_return_key}", 0.02)
            vix_level = cached_data.get("vix_level", 18)
            vix_roc = cached_data.get("vix_roc", 0)
            live_data_success = True
            
            assessment["evidence"]["conflicts"].append(f"Using cached data as of {cached_data.get('timestamp', 'Unknown')}")
    
    # ========== TIER 5: BASELINE ASSUMPTIONS (LAST RESORT) ==========
    if not live_data_success:
        assessment["data_source"] = "Baseline Assumptions"
        assessment["data_provider"] = None
        assessment["data_timestamp"] = "N/A"
        debug_info["data_source"] = "Baseline (all providers failed)"
        
        spy_return = 0.02
        qqq_return = 0.025
        vix_level = 18
        vix_roc = 0
        
        assessment["evidence"]["conflicts"].append("Using baseline assumptions (all live providers failed)")
    
    # ========== COMPUTE PILLARS FROM MARKET DATA ==========
    assessment["data_available"] = True
    
    if spy_return is None:
        spy_return = 0.0
    if qqq_return is None:
        qqq_return = 0.0
    if vix_roc is None:
        vix_roc = 0.0
    raw_trend = spy_return * 5 * sensitivity
    trend_score = max(min(raw_trend, 1.0), -1.0)
    if abs(trend_score) < 0.03:
        trend_score = 0.03 if spy_return >= 0 else -0.03
    
    debug_info["pillars"]["trend"] = {"return": spy_return, "raw": raw_trend, "final": trend_score, "weight": config["trend_weight"]}
    pillar_scores.append(("trend", trend_score, config["trend_weight"]))
    
    if spy_return > 0.05:
        assessment["evidence"]["structural"].append(f"Market Trend: +{spy_return*100:.1f}% (Risk-On)")
    elif spy_return < -0.03:
        assessment["evidence"]["structural"].append(f"Market Trend: {spy_return*100:.1f}% (Defensive)")
    else:
        assessment["evidence"]["structural"].append(f"Market Trend: {spy_return*100:+.1f}% (Mild)")
    
    if vix_level is None:
        vix_level = 18
    if vix_level < 12:
        vol_score = 0.6 * sensitivity
    elif vix_level < 15:
        vol_score = 0.4 * sensitivity
    elif vix_level < 18:
        vol_score = 0.2 * sensitivity
    elif vix_level < 22:
        vol_score = -0.1 * sensitivity
    elif vix_level < 28:
        vol_score = -0.35 * sensitivity
    else:
        vol_score = -0.7 * sensitivity
    
    debug_info["pillars"]["vix_level"] = {"vix": vix_level, "score": vol_score, "weight": config["vix_weight"]}
    pillar_scores.append(("volatility", vol_score, config["vix_weight"]))
    assessment["evidence"]["risk_volatility"].append(f"VIX: {vix_level:.1f}")
    
    if vix_roc > 0.15:
        vix_roc_score = -0.5 * sensitivity
        assessment["evidence"]["risk_volatility"].append(f"VIX ROC: +{vix_roc*100:.0f}% (Rising Stress)")
    elif vix_roc > 0.05:
        vix_roc_score = -0.2 * sensitivity
        assessment["evidence"]["risk_volatility"].append(f"VIX ROC: +{vix_roc*100:.0f}% (Mild Rise)")
    elif vix_roc < -0.10:
        vix_roc_score = 0.4 * sensitivity
        assessment["evidence"]["risk_volatility"].append(f"VIX ROC: {vix_roc*100:.0f}% (Falling)")
    else:
        vix_roc_score = 0.1 * sensitivity
        assessment["evidence"]["risk_volatility"].append(f"VIX ROC: {vix_roc*100:+.0f}% (Stable)")
    
    debug_info["pillars"]["vix_roc"] = {"roc": vix_roc, "score": vix_roc_score, "weight": config["vix_roc_weight"]}
    pillar_scores.append(("vix_roc", vix_roc_score, config["vix_roc_weight"]))
    
    relative_strength = (qqq_return - spy_return) if qqq_return is not None else 0
    raw_breadth = relative_strength * 8 * sensitivity
    breadth_score = max(min(raw_breadth, 1.0), -1.0)
    if abs(breadth_score) < 0.02:
        breadth_score = 0.02 if relative_strength >= 0 else -0.02
    
    debug_info["pillars"]["breadth"] = {"relative_strength": relative_strength, "raw": raw_breadth, "score": breadth_score, "weight": config["breadth_weight"]}
    pillar_scores.append(("breadth", breadth_score, config["breadth_weight"]))
    
    if relative_strength > 0.03:
        assessment["evidence"]["system_alignment"].append("Growth leadership (QQQ outperforming)")
    elif relative_strength < -0.03:
        assessment["evidence"]["system_alignment"].append("Value/Defensive rotation (SPY outperforming)")
    else:
        assessment["evidence"]["system_alignment"].append("Balanced participation")
    
    assessment["debug_pillars"] = debug_info
    
    # ========== COMPOSITE DIRECTION SCORE ==========
    total_weight = sum(p[2] for p in pillar_scores)
    weighted_sum = sum(p[1] * p[2] for p in pillar_scores) / total_weight if total_weight > 0 else 0.05
    
    final_score = max(min(weighted_sum, 1.0), -1.0)
    debug_info["pre_floor_score"] = final_score
    
    if abs(final_score) < 0.05:
        final_score = 0.05 if final_score >= 0 else -0.05
    
    assessment["direction_score"] = round(final_score, 3)
    debug_info["final_score"] = assessment["direction_score"]
    
    signs = [1 if p[1] > 0.1 else (-1 if p[1] < -0.1 else 0) for p in pillar_scores]
    positive_count = sum(1 for s in signs if s > 0)
    negative_count = sum(1 for s in signs if s < 0)
    if positive_count > 0 and negative_count > 0:
        pillar_conflicts = min(positive_count, negative_count)
    
    # ---- MAP SCORE TO LABEL (Score can be non-zero and still Neutral) ----
    score = assessment["direction_score"]
    if score >= 0.40:
        assessment["direction_label"] = "Bullish"
    elif score <= -0.40:
        assessment["direction_label"] = "Bearish / Defensive"
    else:
        assessment["direction_label"] = "Neutral / Transitional"
    
    # ---- DERIVE CONFIDENCE (Adjusted by data source quality) ----
    base_confidence = "Moderate"
    
    if len(pillar_scores) >= 3:
        if pillar_conflicts >= 2:
            base_confidence = "Low"
            assessment["evidence"]["conflicts"].append("Mixed signals across indicators")
        elif pillar_conflicts == 1:
            base_confidence = "Moderate"
        else:
            score_magnitudes = [abs(p[1]) for p in pillar_scores]
            avg_magnitude = sum(score_magnitudes) / len(score_magnitudes)
            if avg_magnitude > 0.3:
                base_confidence = "High"
            else:
                base_confidence = "Moderate"
    elif len(pillar_scores) >= 1:
        base_confidence = "Low"
        assessment["evidence"]["conflicts"].append("Limited market data signals")
    else:
        base_confidence = "Low"
        assessment["evidence"]["conflicts"].append("Insufficient market data")
    
    if assessment["data_source"] == "Cached Market Data":
        if base_confidence == "High":
            base_confidence = "Moderate"
    elif assessment["data_source"] == "Baseline Assumptions":
        base_confidence = "Low"
    
    assessment["confidence"] = base_confidence
    
    return assessment

# -----------------------------------------------
# COMPUTE ALL HORIZONS (SOURCE-DEPENDENT)
# -----------------------------------------------


def compute_confidence_modulation(horizon_key, snapshot_df=None):
    """
    Compute confidence adjustment based on intraday volatility signals.
    CRITICAL: This modulates CONFIDENCE only - never affects direction score.
    
    Returns:
        - confidence_adjustment: integer (-2 to +1) representing level shifts
        - factors: list of contributing factor descriptions
        - raw_metrics: dict of computed metrics for display
    """
    confidence_adjustment = 0
    factors = []
    raw_metrics = {}
    
    horizon_sensitivity = {
        "short": 1.0,
        "intermediate": 0.6,
        "long": 0.25
    }
    sensitivity = horizon_sensitivity.get(horizon_key, 0.5)
    
    try:
        end_date = datetime.now()
        start_date = end_date - timedelta(days=30)
        start_str = start_date.strftime("%Y-%m-%d")
        end_str = end_date.strftime("%Y-%m-%d")
        
        vix_close = fetch_market_data("^VIX", start_str, end_str)
        
        if len(vix_close) >= 5:
            current_vix = float(vix_close.iloc[-1])
            vix_20d_avg = float(vix_close.tail(20).mean()) if len(vix_close) >= 20 else float(vix_close.mean())
            vix_5d_avg = float(vix_close.tail(5).mean())
            
            raw_metrics["vix_current"] = current_vix
            raw_metrics["vix_20d_avg"] = vix_20d_avg
            
            vix_vs_norm = (current_vix - vix_20d_avg) / vix_20d_avg if vix_20d_avg > 0 else 0
            raw_metrics["vix_vs_norm"] = vix_vs_norm
            
            if current_vix > 25:
                adjustment = -2 * sensitivity
                factors.append(f"Elevated VIX: {current_vix:.1f} (stress regime)")
            elif current_vix > 20:
                adjustment = -1 * sensitivity
                factors.append(f"VIX above normal: {current_vix:.1f}")
            elif current_vix < 14:
                adjustment = 0.5 * sensitivity
                factors.append(f"Low volatility environment: VIX {current_vix:.1f}")
            else:
                adjustment = 0
                factors.append(f"VIX normal range: {current_vix:.1f}")
            confidence_adjustment += adjustment
            
            if len(vix_close) >= 3:
                vix_1d_ago = float(vix_close.iloc[-2])
                vix_roc = (current_vix - vix_1d_ago) / vix_1d_ago if vix_1d_ago > 0 else 0
                raw_metrics["vix_roc_1d"] = vix_roc
                
                if vix_roc > 0.10:
                    adjustment = -1.5 * sensitivity
                    factors.append(f"Rapid VIX expansion: +{vix_roc*100:.1f}% 1D")
                elif vix_roc > 0.05:
                    adjustment = -0.5 * sensitivity
                    factors.append(f"VIX rising: +{vix_roc*100:.1f}% 1D")
                elif vix_roc < -0.05:
                    adjustment = 0.3 * sensitivity
                    factors.append(f"VIX contracting: {vix_roc*100:.1f}% 1D")
                else:
                    adjustment = 0
                confidence_adjustment += adjustment
            
            if len(vix_close) >= 10:
                vix_returns = vix_close.pct_change().dropna()
                vol_of_vol = float(vix_returns.tail(10).std())
                raw_metrics["vol_of_vol"] = vol_of_vol
                
                if vol_of_vol > 0.08:
                    adjustment = -1 * sensitivity
                    factors.append(f"High vol-of-vol: {vol_of_vol*100:.1f}% std")
                elif vol_of_vol < 0.03:
                    adjustment = 0.3 * sensitivity
                    factors.append(f"Stable volatility regime: {vol_of_vol*100:.1f}% std")
                else:
                    adjustment = 0
                confidence_adjustment += adjustment
        
        if snapshot_df is not None and "alpha_1d" in snapshot_df.columns:
            intraday_alphas = snapshot_df["alpha_1d"].dropna()
            if len(intraday_alphas) > 1:
                intraday_dispersion = float(intraday_alphas.std())
                raw_metrics["cross_wave_dispersion"] = intraday_dispersion
                
                if intraday_dispersion > 0.02:
                    adjustment = -0.5 * sensitivity
                    factors.append(f"Cross-wave dispersion: {intraday_dispersion*100:.2f}% std")
                else:
                    adjustment = 0
                confidence_adjustment += adjustment
        
        if len(vix_close) >= 5:
            vix_5d_range = float(vix_close.tail(5).max() - vix_close.tail(5).min())
            vix_5d_mid = float(vix_close.tail(5).mean())
            compression_ratio = vix_5d_range / vix_5d_mid if vix_5d_mid > 0 else 0
            raw_metrics["vol_compression"] = compression_ratio
            
            if compression_ratio < 0.05:
                factors.append(f"Vol compression: {compression_ratio*100:.1f}% range")
            elif compression_ratio > 0.20:
                adjustment = -0.5 * sensitivity
                factors.append(f"Vol expansion: {compression_ratio*100:.1f}% range")
                confidence_adjustment += adjustment
                
    except Exception:
        factors.append("Limited intraday data available")
    
    confidence_adjustment = max(min(round(confidence_adjustment), 1), -2)
    
    return confidence_adjustment, factors, raw_metrics



def apply_confidence_modulation(base_confidence, adjustment):
    """
    Apply confidence level adjustment.
    Returns new confidence level string.
    """
    levels = ["Low", "Moderate", "High"]
    current_idx = levels.index(base_confidence) if base_confidence in levels else 1
    new_idx = max(0, min(2, current_idx + adjustment))
    return levels[new_idx]

