                if si_spy is None or si_rs_30 is None:
                    return "Data Insufficient"
                spy_above_50 = compute_above_ma(si_spy, 50) if si_spy is not None and len(si_spy) >= 55 else None
                sec_above = si_above_50 if si_above_50 is not None else False
                spy_above = spy_above_50 if spy_above_50 is not None else False
                if sec_above == spy_above and abs(si_rs_30) < 0.05:
                    return "Aligned"
                elif sec_above != spy_above:
                    return "Diverging"
                else:
                    return "Mixed"

