            def compute_volume_intelligence(vol_series, price_series):
                """NOTE 032 - Compute volume participation, confirmation, and anomaly diagnostics."""
                unavailable = {"participation": "Unavailable", "confirmation": "Unavailable", "anomaly": "Unavailable", "volume_vs_50d": None}
                if vol_series is None or price_series is None:
                    return unavailable
                try:
                    vol_series = vol_series.dropna()
                    price_series = price_series.dropna()
                    if len(vol_series) < 55 or len(price_series) < 25:
                        return unavailable

                    current_vol = float(vol_series.iloc[-1])
                    avg_20d = float(vol_series.tail(20).mean())
                    avg_50d = float(vol_series.tail(50).mean())

                    if avg_50d <= 0 or avg_20d <= 0:
                        return unavailable

                    vol_vs_50d = (current_vol / avg_50d) * 100

                    if current_vol > avg_50d * 1.30:
                        participation = "Expanding"
                    elif current_vol < avg_50d * 0.80:
                        participation = "Contracting"
                    else:
                        participation = "Neutral"

                    price_20d_ago = float(price_series.iloc[-21]) if len(price_series) >= 21 else float(price_series.iloc[0])
                    price_now = float(price_series.iloc[-1])
                    price_up = price_now > price_20d_ago

                    if price_up and participation == "Expanding":
                        confirmation = "Positive"
                    elif price_up and participation == "Contracting":
                        confirmation = "Unconfirmed"
                    elif not price_up and participation == "Expanding":
                        confirmation = "Distribution"
                    else:
                        confirmation = "Neutral"

                    if current_vol > avg_50d * 2.00:
                        anomaly = "Elevated"
                    elif current_vol < avg_50d * 0.60:
                        anomaly = "Drying Up"
                    else:
                        anomaly = "Normal"

                    return {
                        "participation": participation,
                        "confirmation": confirmation,
                        "anomaly": anomaly,
                        "volume_vs_50d": vol_vs_50d,
                    }
                except Exception:
                    return unavailable

