                _html += f'<td style="padding:8px 12px;">{_fv(_v30)}</td>'
                _html += f'<td style="padding:8px 12px;">{_fv(_v90)}</td>'
                _html += f'<td style="padding:8px 12px;">{_fv(_v365)}</td>'
