                if _s2_w_df.empty:
                    continue
                _s2_w_neg = []
                for _s2_cc, _s2_cn in _s2_components.items():
                    if _s2_cc not in _s2_w_df.columns:
                        continue
                    _s2_w_avg = pd.to_numeric(_s2_w_df[_s2_cc], errors="coerce").mean()
                    if _s2_w_avg < -0.005:
                        _s2_w_neg.append((_s2_cn, _s2_w_avg))
                if len(_s2_w_neg) >= 2:
                    _s2_c_strs = [f"{c}: {v*100:+.2f}%" for c, v in _s2_w_neg]
